(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-7"] = [{"a": [154], "v": 1, "p": 347, "ev": 1, "ep": 350, "sid": 348, "t": "قوله - عز وجل -:\n﴿وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ﴾⟪2:154⟫\nالآية (154) - سورة البقرة.\nقد تقدم أن الحياة تقال على أوجه، وكل واحدة يقابلها موت، الأول: في القوة النامية التي بها الغذاء والشهوة إليها، وذلك موجود في النبات والحيوان والإنسان، ولذلك يقال: نبات حي، والثاني في القوة الحساسة التي بها الحركة المكانية وهي موجودة في الحيوان والإنسان دون النبات، والثالث القوة العاملة العاقلة [وبها يكون العقل والعلم] وهي في الإنسان دون\n⟦1:348⟧\nالحيوانات والنبات وبها يتعلق التكليف، وقد يقال للعلم المستفاد الحقيقي، والعمل الصالح حياة، وعلى ذلك قوله تعالى: ﴿ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ﴾⟪8:24⟫ وقيل: \" المحسن حي وإن كان في دار الأموات، والمسيء ميت وإن كان في دار الأحياء \"، ونرجع إلى معنى الآية فنقول: إن بعض المعتزلة لم يعتبر في ذلك تفصيلا، وقال عني: بإثبات الحياة ونفى الموت عن الشهداء يوم الحساب، لا في الحال قالا ولا اختصاص لهم، بل إنما علق الحكم بهم، لأنه في ذكرهم، ولو ذكر معهم غيرهم\nلذكرهم بحكمهم واستجهل من قال إذ! م أحياء وقال: قد علم أن رسول الله «- صلى الله عليه وسلم -» والشهداء في\nقبورهم، وهم لا يأكلون ولا يشربون، واستجهاله لن خالفه هو لأنه فرغ إلى الحس الذي قد نفى الله تبارك وتعالى بقوله: ﴿وَلَٰكِن لَّا تَشۡعُرُونَ﴾⟪2:154⟫ أي: لا تحسون ولا تدركون ذلك بالمشاعر أي الحواس تنبيها أن ذلك مما السبيل إلى معرفته الفرق إلى العقول وإلى الاعتبارات الصحيحة [دون الحواس] وإما علي طريقة غيرهم فمعلوم، وقد أجمعوا على أنه لا يثبت لهم الحياة التي بها النمو والغذاء ولا الحياة التي بها الحس، فإن فقدانهما عن الميت محسوس ومعقول، فبعض المفسرين اعتبر المعنى الآخر الذي هو العلم المستفاد والعمل الصالح، فقال: إن الله تعالى نهى أن يسمى الشهداء أمواتا في حكم الدين، فقال: لا تقولوا لهم ما قال المشركون، ولكن قولوا هم أحياء في الدين، وهذا صحيح ...\nوبعضهم اعتبر الحياة المختصة بالإنسان، وقال: إن هذه الحياة مختصة بالقوة المروية المسماة تارة الروح، وتارة النفس، وتارة النسمة قال: والموت المشاهد هو مفارقة هذه القوة أي الروح البدن، فمتى كان الإنسان محسنا كان منعما بروحه، [مسرورا بمكانه] إلى يوم القيامة، وإن كان مسيئا كان به معذبا، وإن الحسن يعلم في بذلك بعد موته، وإلى هذا ذهب الحكماء ودلوا عليه بالبراهين\n⟦1:349⟧\nوالأدلة وهو مذهب أصحاب الحديث، ويدل على صحته الأخبار والآيات المروية عن النبي - صلى الله عليه وسلم -، بل إليه ذهب عادة أصحاب الملل كلها ولم يخالفهم إلا جماعة من المعتزلة، حيث جعلوا الأنواع أعراضا لا قوام لها إلا بالأجسام، وأنها مهما فارقت الأجسام بطلت، ومما دل على صحة ذلك قوله عليه السلام: \" الأرواح جنود مجندة، فما تعارف منها ائتلف، وما تناكر منها اختلف \" وما روى أمير المؤمنين علي عن النبي صلي الله عليه وسلم أنه قال: \" فإن الله خلق الأرواح قبل الأجساد بألفى عاما، إن الروح في قناديل معلقة تحت العرش \"، وقال في أرواح الشهداء ما عرفت وما روي عنه- عليه السلام- \" إن الميت ليرد على جماعة من الأموات، فلا يزالون يسألونه عن معارفهم وجيرانهم، وهو يخبرهم ويصف لهم حتى يجري ذكر الرجل \" فيقول ة قد مات قبلي بمدة، فيقولون: إنا لله، سفل به، وإن كان من الصالحين قالوا: على به ومعلوم أنه لم يرد عليهم بالأشباح، وإنما ذلك الإلقاء بالأرواح وروي أنه لما قتل [من قتل] من صناديد قريش يوم بدر، فجمعت جثثهم في قليب، ثم أقبل النبي - صلى الله عليه وسلم -، فخاطبهم بقوله: \" هل وجدتم ما وعد ربكم حقا؟ فإني وجدت ما وعدني ربي حقا \"، قيل: يا رسول الله: أتخاطب جيفا؟\nفقال: [ما أنتم بأسمع منهم ولكنهم لا يقدرون على الجواب] وما روي أنه قال: \" رأيت نسمة\n⟦1:350⟧\nأدم \" إلى غير ذلك من الأخبار، وعلى ذلك قوله عز وجل ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫، وقال في آل فرعون: ﴿ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ﴾⟪40:46⟫، وهذا يعني به قبل القيامة بدلالة أخر الآية وهو قوله تعالى: ﴿وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ﴾⟪40:46⟫ وإلى هذا المعنى ذهب جماعة الصحابة والتابعين، قال مجاهد: \" يرزقون من ثمر الجنة فيجدون ريحها وليسلوا فيها \" ..\nوقال ابن عباس والربيع وغيرهما: \" أرواح الشهداء في أحواف طير خضر ترد أنهار الجنة وتأكل من ثمارها \""}, {"a": [155], "v": 1, "p": 350, "ev": 1, "ep": 353, "sid": 351, "t": "قوله - عز وجل -:\n«ولنبونكم بشي ولنبلونكم بشيء من الخوف والجوع ونقص من الأموال والأنفس والثمرات وبشر الصابرين»\nالآية (155) - سورة البقرة.\nالبلاء: المبالغة في الاختبار، كأنك [أبليته] وأخلقته من كثرة ما اختبرته به، ولذلك يقال: بليت فلانا أي خبرته، والكلام في نسبة الابتلاء إلى- عز وجل- كما تقدم في.\nقوله: ﴿وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ﴾⟪47:31⟫ وإنما يراد به ظهور الفعل دون حصول العلم، والخوف توقع مكروه، والجوع استدعاء البدن عوض ما تحلل عنه، ونقص الأموال: ذهاب بعض ما حوته اليد، ونقص الأنفس : افتقاد الإنسان بعض قواه في ذاته، أو بعض جوارحه [أو سمعه أو بصره] أو بعض أقاربه وأخلائه، ونفس الثمرات: فقد المتوقع من الدخل والربح، وهذه الجملة مشتملة على محن الدنيا كلها.\nإن قيل: هل ابتلاء الله الناس بهذه النوائب عام لهم أم خاص لبعضهم؟ وهل ذلك في زمان دون زمان؟ أو فبم كل زمان؟\n⟦1:351⟧\nقيل: أما بالنظر الخاصي فعام لهم وفي كل زمان، وذاك أن الناس لا ينفكون في الدنيا في شيء من الحالات عن شي ما من المحن، بل في حال اليسار يساق بهم إلى محنة فإذا ما هم في محنة وإن كانوا في صحة ولهذا روي:: كفى بالسلامة داء \" ..\nوقال الشاعر:\nإذا كان الشباب يعود شيبا ...\nوهما فالحياة هي الحمام\nفالعاقل بتفكره يعلم أن ماله وبدنه وذويه ونعمه عارية مستردة، فإذا عرضت له نائبة كان له من الصبر مطية لا تكبو، ومن الرضا بقضاء الله سيف لا ينبو، وإما بنظر أعم من ذلك، فإن الله تعالي لا أجرى عادة الدنيا أن لا تنفك من هذه الآفات المذكورة، وأنها قد تنال الأخيار كما تنال الأشرار، جعلها ابتلاء لأوليائه لكي إذا تلقوها بالصبر حط بها وزرهم، وإلا عظم به أجرهم.\nوخص بعض المفسرين هذه الأشياء فقال: أراد بالخوف: ما ينال في مجاهدة العدو وبالجوع: صوم شهر رمضان وبنقص من الأموال، ما أوجب من الزكوات، وبنقص الأنفس: الأمراض وبنقص الثمرات: الصدقات وجعل بعضهم هذه الأشياء المحن الظاهرة العامة، لكن خص المخاطبين بأنهم أصحاب النبي- عليه وعليهم السلام خاصة، فقال: \" إن الله- عز وجل أبلاهم بهذه الأشياء الظاهرة للحواس \" المتبينة للكل ليعلم من بعدهم أنهم لم يتحروا في أتباع النبي- عليه السلام- طلب عرض، بل تبعدوه لتحققهم بمعرفة الحق وظهور الحجج، وجعل بعض المعتزلة المخاطبين والمحن\n⟦1:352⟧\nالمذكورة جميعا مخصوصين، وقال ذلك كل في أصحاب النبي- عليه السلام-، وعني بالخوف: خوفهم من الأعداء وبالجوع فقرهم بتشاغلهم بالجهاد، ونفس الأموال: للانقطاع عنه إلى الجهاد عن عمارة بساتينهم، والأنفس: للقتل في سبيل الله، قال: وكل دلك من فعل الله- عز وجل- لا من الكفار، وجعل دلك مخصوصا تفاديا كما أن يكون بعمومه ناسبا إلى الله تعالي فعلا قبيحا ولو اتسع نظره، لأمن مما يحذره، وعلى هذا القبيح والسخط للقضاء ليس يعني شيئا، وإنما يريد تصور ما خلق الإنسان لأجله، والقصد له والاستهانة بما يعرض في طريق الوصول فأمر تعالى ببشارة من اكتسب العلوم الحقيقية وتصورها، وقصد هذا المقصد ووطن نفسه عليه.\nوعلى هذا النحو قوله: عز وجل: ﴿وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ﴾⟪47:31⟫، وقوله: ﴿أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ﴾⟪29:2⟫، وقوله: ﴿وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ﴾⟪21:35⟫\nإن قيل: لم فصل بقوله: ﴿وَلَا تَقُولُواْ﴾⟪2:154⟫ الآية بين هذه الآية والتي قبلها من قوله: ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ﴾⟪2:45⟫ وهي بمعزل منهما؟ قيل: بل هي متصلة بهما، لأنه لما حث على الصبر وأكثر الصبر إنما لطلب الحياة ولما يعين علي الحياة، بين تلك الآية أن ذلك الصبر يوصل إلى حياة باقية كما قال: ﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫ وكما قال- عليه السلام: \" اللهم لا عيش إلا عيش الأخرة \"\n⟦1:353⟧\nليرغبنا في الصبر، ثم لما قرر ذلك أنبأ عما يحملنا من هذه المحن كي يخف علينا تحملها، ثم ختمه بقوله: ﴿وَبَشِّرِ ٱلصَّٰبِرِينَ﴾⟪2:155⟫"}, {"a": [156], "v": 1, "p": 353, "ev": 1, "ep": 354, "sid": 354, "t": "قوله - عز وجل -:\n﴿ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ﴾⟪2:156⟫\nالآية (156) - سورة البقرة.\nالمصيبة من: أصاب السهم، إذا بلغ على صواب، وهي في الأصل صفة، وليس يريد بالقول اللفظ فقط، فإن التلفظ بذلك مع الجزع القبيح والسخط للقضاء ليس يعني شيئا وإنما يريد تصور ما خلق الإنسان لأجله، والقصد له والاستهانة بما يعرض في طريق الوصول، فأمر تعالى ببشارة من اكتسب العلوم الحقيقية وتصورها، وتصور بها المقصد ووطن نفسه عليه.\nفإن قيل: ولم قلت إن الأمر بالصبر يقتضي العلم، وما الصبر من العلم؟\nقيل: الصبر على الحقيقة إنما يكون لمن عرف فضيلة مطلوبة، ولهذا قال الخضر لموسى لما علم أن ليس يرف مقصده في فعله قال: ﴿قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ۝ وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا﴾⟪18:67-68⟫ فدل أن حقيقة تحمل الصبر لأبد له من معرفة المقصود به، وقال عليه السلام \" أعطيت أمتي ما لم يعط أحد، قال يعقوب [عند المصيبة] يا أسفي، وأعطيت أمتي أن يقولوا: ﴿إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ﴾⟪2:156⟫، وقال عليه السلام: \" من استرجع عند المصيبة جبر الله مصيبته، وأحسن عقباه، وجعل\n⟦1:354⟧\nله خلقا يرضاه \"، وقال عمر في ذلك: \" نعم العدلان، ونعم القلادة \"، وحقيقة الرجوع إليه تتبين في قوله- عز وجل- ﴿كَمَا بَدَأَكُمۡ تَعُودُونَ﴾⟪7:29⟫ فهو أدق معنى مما قدره من قال: (إنا راجعون) إلى أن لا يملك أمورنا غيره كما كنا في الابتداء، فجعل ذلك رجوعأ لهم."}, {"a": [157], "v": 1, "p": 354, "ev": 1, "ep": 355, "sid": 355, "t": "قوله - عز وجل -:\n﴿أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ﴾⟪2:157⟫\nالآية (157) - سورة البقرة.\nالصلاة وإن كانت في الأصل الدعاء، فهي من الله البركة على وجه، والمغفرة على وجه، وهي الرحمة وإن كانتا متلازمتين فهما مفترقتان في الحقيقة، وإنما قال:) صلوات) على الجمع تنبيها على كثرتها منه وإنها حاصلة في الدنيا توفيقا وإرشادا، وفي الآخرة ثوابا ومغفرة، ثم بين أن من كان كذلك فهو المهتدي تنبيها علي ملازمة هذه المعاني الصبر.\n⟦1:355⟧"}, {"a": [158], "v": 1, "p": 355, "ev": 1, "ep": 356, "sid": 356, "t": "قوله تعالى:\n﴿إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ﴾⟪2:158⟫\nالآية (158) - سورة البقرة.\nالصفا: الحجارة الصافية عن الطين، والمروة: ما كان صلبا شديدا، والشعائر جمح الشعيرة، أي علامة محسوسة، ومعالم الحج مشاعر وشعائر، وسمي الهدى المعلم بذلك، والحج: القصد بمعرفة، ومنه الحجة، والعمرة في الأصل الزيارة المقتضية لعمارة المودة في الأصل، فكان الحج هو الزيادة والعمرة عمارتها، ولهذا يتأخر ذكرها في القرآن، ويجب الدم على من قدمها في أشهر الحج\nأوقرنها به لتقديم ما من حقه أن يؤخر، وهذا ينبه أن الإفراد أفضل من التمتع والقرآن\nفإن قيل: فكيف ندب النبي- عليه السلام أصحابه إلى فسخ الحج والانتقال إلى العمرة، على هذا قيل: إنه أراد أن ينزلهم عن اعتقادهم أنما الاعتبار في أشهر الحج من أكبر الكبائر، والجناح الميل إلى الإثم، أصله من الجناح و \" جنح الطائر \" حرك جناحه، وبه شبه سير الإبل، فقيل جنحت الإبل في السير، كقوله طارت، وجنوح السفينة لتشبه السابح بالطائرة ولهذا قيل: السابح طائر في الماء، والطائر سابح في الهواء، وجنح الظلام ألقى جناحه، ألا ترى أنه يقال: ألقى الظليم أرواقه كما يقال: ألقى الظالم أرواقه؟ والتطوع: تكلف طوع أي انقياد، وهو في التعارف التبرع بما لا يلزم، وإنما قال: لا جناح وذلك واجب، لأن العرب كانت تكره السعي في الجاهلية وقيل: أنها كرهت لصنمين كانا قيل عليهما يعتقدون أنما لهما السعي، فتأثموا لذلك فأنزل الله تعالى الآية، وأما الوجوب: فمستفاد من الخبر، وهو قوله:) أسعوا) فإن الله كتب عليكم السعي، وروي أن عروة قال لعائشة- رضي لله عنها: \" ما أرى جناحي أن لا يطوف بين الصفا والمروة فقالت: \" بئسما قلت، لو كان كذا لقال: \" أن لا يطوف بهما \".\n⟦1:356⟧\nوقد قيل: إن قوله: \" لا جناح \" كلام تام، وإن قوله: ﴿عَلَيۡهِ أَن يَطَّوَّفَ﴾⟪2:158⟫ استئناف يقتضي الوجوب، وقرئ (يطوع) على تقدير \" يتطوع \"، وبين بقولها: (فمن تطوع) أي من زاد على ذلك، فإن الله عز وجل- يبينه فشكر الله- عز وجل- للعبد الإحسان إليها وقد تقدم أن الشكر كما بالقول يكون بالفعل، وعلى ذلك قوله عز وجل: ﴿ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ﴾⟪34:13⟫، وليس شكر الأرفع للأوضع إلا بقبوله حمده والإفضال عليه بذلك. . . قوله - عز وجل -:"}, {"a": [159], "v": 1, "p": 356, "ev": 1, "ep": 357, "sid": 357, "t": "﴿أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّٰعِنُونَ﴾⟪2:159⟫\nالآية (159) - سورة البقرة.\nاللعن الإبعاد على وجه الطرد، وصار في التعارف دعاء إذا قيل: لعنه الله والبينة والهدى وإن كانا متلازمين فإنهما مختلفان، فإن البينات يشار بها إلى الآيات المنزلة والهدى إلى ما يستدل به من الأمارات، وقيل: الأمة في أهل الكتاب العالمين أمر النبي عليه السلام، وقيل: هي عامة، وسواء خصت الآية أم لم تخص، فحكم الله عام في أن من كتم علما عن مستحق له استحق العقوبة، وعلى هذا قال عليه السلام: \" من سئل عن علم فكتمه ألجمه الله بلجام من نار \" وليس ذلك بمناف يقول من منع حقائق الحكمة عمن لا يستحقها، فإن ذلك دعاء له أن يترشح لقبولها وحسن سماعها وحفظها لئلا يستعين بها في طريق السر، فليس العلم بأهون على الله- عز وجل- من المال الذي هو عرض حاضر يأكل منها البر والفاجر، وقد منع أن يمكن منه السفيه الذي لا يحسن مراعاته، فقال:\n⟦1:357⟧\n﴿وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا﴾⟪4:5⟫.\nواللاعنون: قيل هو عام في الملائكة والناس ودواب الأرض، وما روي أنه تلعنهم الهوام فتقول: (منعنا القطر بمعاصي بني آدم)، فذلك تنبي أحوالها أنهم مستحقون من الله اللعن، فكأنه ناطقة بذلك كقولك لمن رأيت له أثرا قبيحا على فرسه: \" إن فرسك تشكوك وتلعنك \"، وعلى ذلك قول الشاعرفي ناقته:\nيقول إذا ادرأت لها وضيني ...\nأهذا دينه أبدا وديني\nوأما ما يتصوره بعض الناس في أن يكون للهوام تمييز ولعن بالقول، فذلك ممتنع بوجه مخصوص ليس هذا موضع شرحه."}, {"a": [160], "v": 1, "p": 357, "ev": 1, "ep": 358, "sid": 358, "t": "قوله - عز وجل -:\n﴿إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:160⟫\nالآية (160) - سورة البقرة.\nلما كانت التوبة استدراك ما ارتكب من المآثم بما يغمره هن أفعال الخير على ما تقدم ذكره، فمن يكتم البينات والهدى عن الناس فإنه مع جنايته في نفسه أفسد الناس ومنع حقهم، فإذن لا يكفيه من التوبة أن يغير نيته بالندم والعزم على أن لا يعاود مثله حتى يصلح ما أفسده بقدر طاقته ويظهر ما كتمه، كما أن من غصبه مالا يكون موفيا حق التوبة حتى يرد ما غصبه، وضمن تعالى\nأنه يتوب عليهم إذا فعلوا ذلك وبين بقوله: ﴿وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:160⟫ أنه ليس يفعل ذلك بهم فقط، بل يتوب على كل تائب، ولمي حق توبته ويرحمه.\n⟦1:358⟧"}, {"a": [161, 162], "v": 1, "p": 358, "ev": 1, "ep": 358, "sid": 359, "t": "قوله عز وجل:\n﴿إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ ۝ خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ﴾⟪2:161-162⟫\nالآيتان (161، 162) - سورة البقرة.\nلما بين في الأول من تاب من ذنبه تاب عليه ورحمه بين في هذا أن من مات على كفره فالعقوبة لازمة له،\nإن قيل: أليس قد قال في الأول: ﴿أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ﴾⟪2:159⟫ فلم أعاد ههنا فيل لأمرين، أحدهما أنه عم ههنا، وخص في الأولى الذين يكتمون الحق والثاني أنه في الأولى ذكر أن اللعنة تتوجه إليهم وهم يستحقونها، وفي الثانية ذكر أن اللعنة تقر عليهم، ولهذا قال عليهم:\nن قيل.\nهل الناس عام حتى أكده بأجمعين؟\nقيل: نعم، وذلك أن المؤمنين وصالحي العباد يلعنونهم، وهم يلعن بعضهم بعضا: كما قال: ﴿يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا﴾⟪29:25⟫، وكل يلعن نفسه ويلعن بعض جوارحه وقواه بعضة، كما تشهد عليه، وقوله: ﴿خَٰلِدِينَ فِيهَا﴾⟪2:162⟫ قيل: في اللعنة، وقيل: في النار، وهما في الحقيقة واحد، فكل من عليه اللعنة فهو في النار، وقرئ ﴿وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ﴾⟪2:161⟫، ويكون ذلك عطفآ\nعلى المعنى دون اللفظ."}, {"a": [163], "v": 1, "p": 358, "ev": 1, "ep": 359, "sid": 359, "t": "قوله - عز وجل -:\n﴿وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ﴾⟪2:163⟫\nالآية (163) - سورة البقرة.\nقد تقدم الكلام في الواحد إذا وصف به البارئ عز وجل وقوله: ﴿وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ﴾⟪2:163⟫ يجوز أن يكون خطابا عاما أي المستحق منكم العبادة وهو إله واحد لا أكثر، ويجوز أن يكون خطابا للمؤمنين،\n⟦1:359⟧\nوالمعنى: الذي يقصدونه إله واحد تنبيها أنكم لستم كالكفار الذين يعبدون آلهة من الأصنام والشيطان والهوى وغير ذلك.\nإن قيل: ما فائدة الجمع بين ﴿وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ﴾⟪2:163⟫ وبين ﴿لَّآ إِلَٰهَ إِلَّا هُوَ﴾⟪2:163⟫ وأحدهما يبنى على الآخر؟\nقيل: لما بين بقوله: ﴿وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ﴾⟪2:163⟫ أنه المقصود بالعبادة أو المستحق لها، وكان يجوز أن يتوهم أن يوجد إله غيره ولكن لا يعبد أولا يستحق العبادة أكده بقوله: ﴿لَّآ إِلَٰهَ إِلَّا هُوَ﴾⟪2:163⟫، وحق لهذا المعنى أن يكون مؤكدا ويكرر عليه الألفاظ [الملخصة]، إذ هو مبدأ مقصود العبادة ومنتهاه."}, {"a": [164], "v": 1, "p": 359, "ev": 1, "ep": 361, "sid": 360, "t": "قوله عز وجل:\n﴿إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ﴾⟪2:164⟫\nالآية (164) - سورة البقرة.\nاختلاف الليل والنهار: أن يخلف كل واحد منهما الأخر، كقوله عز وجل: ﴿وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ﴾⟪25:62⟫، وقوله: ﴿يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ﴾⟪39:5⟫ وقوله: ﴿يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ﴾⟪24:44⟫، والفلك: السفينة المدورة، وبه شبه فلك السماء، ولذلك استعمل فيه السباحة وفلكة المغزل، وفلكت الجارية صار ثديها كفلكة، وفلكت الجدي: وضعت فلكه على لسانه يمنعه عن الرضاع، والفلك يقال للواحد والجمع، وذلك أنه يقال للواحد فلك، وفلك نحو: نخل ونخل وعرب وعرب، وعجم وعجم، ومن قال: فلك يجمعه على فلك نحو أسد وأسد فتداخل الواحد والجمع من لغتين، والبث إظهار\n⟦1:360⟧\nما كان خفيا عن الحاسة هما كان أو غيره، والدبيب أصله حكاية صوب المشي، ثم قيل: دب إذا مشى، ويقال لكل ما يمشي دابة، وتم خص بالفرس، والدب خص بضرب من السباع، وأن الدبة والدبدبة فاعتبارا بصوتهما، والتصريف: صرف الشيء من وجه إلى وجه، وصريف الباب منه، لكن اعتبر فيه الصوت، فبني بناء الأصوات كالنهيق والشهيق وغير صارف تصرف الفحل إلى نفسها بإظهار شبقها، والصرف والصريف المصروف عن الكدورة، لكن خص الصريف باللبن والصرف بسائر الأشربة، وقوله: ﴿وَتَصۡرِيفِ ٱلرِّيَٰحِ﴾⟪2:164⟫ يجوز أن يكون تقديره: تصريف الله الرياح، وأضيف إلى المفعول، وتصريف الرياح والسحاب، فيكون مضافا إلى الفاعل والسحب جر الثوب، والسحابة هو لما تجره الريح، والتسخير القهر علي الفعل وهو أبلغ من الإكراه، فإنه حمل الغير علي الفعل بلا إرادة منه على وجه كامل الرحى على الطحن،\nإن قيل: لم جمع السماء وأفرد الأرض في كل القرآن؟\nقيل: لأن السماوات لما كانت في الحقيقة سبعا وطبائعها مختلفة على ما ذكر أصحاب هذه الصناعة، وكل واحدة مستمدة القوة مما فوقها ومعطية ما دونها، والأرض وإن كانت سبعا، فليس على ذلك الوجه، لأنها بالأقاليم لا بالطبقات المتراكمة تراكب السماء وطبيعتها واحدها، ولهذا قال: ﴿وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ﴾⟪65:12⟫ فترك اللفظ مفردا، ونبه بمثلهن على العدل الذي يعد به الأقاليم، وإنما ذكر هاهنا لفظ الخلق ، لأنه مشتمل علي الإبداع والصنع والتسخير، وخص فعل الله تعالى بذلك لكونه موضوعا للتقدير المقتضي للأحكام، وهو تعالى أحد الحاكمين، ونبه تعالي على وحدانيته بالتفكر في الموجودات وذكر من آياته مالا يخفى أمر صنعته على ذوي الحواس والعقول ليستدل به كل على قدر فهمه ويقف منه على معارف بمبلغ علمه.\nإن قيل: كان الوجه أن يعقد ذكر السماوات والأرض واختلاف الليل والنهار بتصريف الرياح والسحاب التي هي من آثار الجو ومختصة بفعل الله- عز وجل-، ثم يعرج على ذلك الفلك التي هي\n⟦1:361⟧\nفي الأرض وفيها أثر أيدي البشر، حتى يكون على النسق، قيل إن إيجاد البحر مقدم على إيجاد الأمطار والرياح والسحاب، فكل ذلك إنما ينشأ عن البحار الساطع من رطوبة البحار ويبوسة الأرض، وذلك مبين في كتب المعنيين بمعرفة هذه الصنعة، ولما لم يكن فرق بين أن يقال: ﴿وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ﴾⟪2:164⟫ وبين أن يقال: (والبحر الذي تجري فيه الفلك) في أن القصد الأول بالآية أن يعرف منفعة البحر وإن أخر في اللفظ، وقدم ذكر الفلك التي هي من صنعتنا، ونحن بصنعتنا أعرف منا بصنعته.\nقدم ذكر الفلك لننظر منها إلى أثار الله تعالى، وقال بعض الناس:\nلم يعن بالفلك والبحر المحسوسين فقط، بل عنى بالبحر كل شبها وحيرة ومشقة، وبالفلك ما فيه إيقاد البشر من فائض النور والعقل أمدهم به، وغير ذلك من المعادن المعقولات والمحسوسات، وقد تقدم أن من الناس من قال: الإشارة بالماء في نحو هذه المواضع إلى العلوم التي بها الحياة الأبدية وما في الأرض إلى النفوس التي بها تحيا الحياة الأبدية، ولما ذكر الله تعالى في الآية الأولى:\n) وإلهكم إله واحد) جعل هذه الآية دلالة عليه تنبيها أن كل موجود لا ينفك من أن يكون مكونا غير مكون، أو مكونا من وجه مكونا من وجه أو مكونا وغير مكون، ومحال أن يكون كل مكون مكونا لأن ذلك يؤدي إلى ما لا يتناهى، فإذن لابد أن تنتهي الموجودات إلى مكون غير مكون، وذلك هو الباري- عز وجل-، فنبه أن أثر الصنعة موجود في هذه الأشياء، فلابد أن تكون مكونة، وهذا هو الدلالة على وحدانيته علي طريق الجملة .."}, {"a": [165], "v": 1, "p": 361, "ev": 1, "ep": 363, "sid": 362, "t": "قوله - عز وجل -:\n﴿وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ﴾⟪2:165⟫\nالآية (165) - سورة البقرة.\nالند: المثل في الجوهر، وقد تقدم، والحب أصله من الحب، وبه شبه حبة القلب وحبيبه يقال على وجهين، أحدهما: أصبت حبة قلبه، نحو كبدته وفادته، والثانية أصبته بحبة القلب، نحو: رمحته وعنيته، أصبته بالعين، فقولك: حببته وأحببته هو في اللفظ فعل، وفي الحقيقة قد يكون انفعالا، لأن المحب يكون منفعلا للمحبوب، وإذا أستعمل في الله تعالى فقيل: \" أحب الله فلانا \"، فليس إلا على\n⟦1:362⟧\nسبيل الفكر والمعنى: أصاب الله تعالى حبة قلبه، فجعلها لنفسه مصونة عن الهوى والشيطان وسائر أعداء الله، والمحبة إرادة ما تراه أو تظنه خيرا، وهي أربعة أضرب بحسب أعراض الناس في أمورهم، اللذة، والنفع، والخير المحض، والمركب من اللذة، والنفع [لمحبة المغني له والمغني بعضهما لبعض]، وكل محبة ينقطع سببها انقطعت بانقطاعها، ولما كانت الشهوات البدنية والمنافع الدنيوية منقطعه، فالحب الذي يجلبانه منقطع لا محالة بانقطاعهما، ولما كان الخير المحض باقيا، كان الحب الذي يجلبه باقية ببقائه، ولما بين تعالى توحيده والدلالة عليه ذكر بعد أن مع ظهور الآيات المنبئة عنها من الناس من يتخذ ندا لنفسه بحبه، ويراعيه مراعاة الله تعالى ثم نبه بقوله: ﴿وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ﴾⟪2:165⟫ أن محبتهم لأندادهم منقطعة، فإن أسبابها المقتضية لها منقطعة، ومحبة المؤمنين له دائمة، إذ هو دائم والند المشار سواء كان صنما معبودا أو رئيسا مخدوما، أو مالا منعقدا، أو إنسانا معشوقا، فإن كل ذلك محبوب لن يراعيه من وجه ومعبود من وجه ثم بين بقوله: ﴿وَلَوۡ تَرَىٰٓ﴾ ما أعد هم من العذاب الأليم، فإذا قرئ بالياء، فإن ما بعده هو مفعول يرى وجواب \" لو \" محذوف، وقيل: إن القوة مفعول الفعل المحذوف الذي هو جواب، كأنه قيل: لرأوا أن القوة لله جميعا، وإذا قرئ\nبالتاء، فخطاب النبي على طريق التعظيم، ومعناه: أنك مع علمك بأحوال القيامة لو رأيت لتعجبت، وقوله: ﴿أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا﴾⟪2:165⟫، قيل: هو بدل من الذين، وهو ضعيف وقيل: هو مفعول الفعل المقدر للجواب، وقيل: تقديره: لأن، وقد قرئ إن مكسورة ولا يكون إلا علة والمفعول محذوف.\n⟦1:363⟧"}, {"a": [166], "v": 1, "p": 363, "ev": 1, "ep": 364, "sid": 364, "t": "قوله - عز وجل -:\n﴿إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ﴾⟪2:166⟫\nالآية (166) - سورة البقرة.\nالسبب: أصله الحبل الذي تشد به (الخيم) ويرتقي به الشجر، ثم جعل عبارة عن كل ذريعة من مواصلة وذمة، والسبب والسبيبة للشقة من الثياب تشبيها به في الهيئة، وبعض الصنعة، وسببته في الأصل كناية معناه: أصبت سببه، ولكنه سمى الإصبع سبابه، لكونها مشيرة بالسب، كما قيل لهامسبحة لإشاراتها بالتسبيح، وتقدير الآية: ﴿وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ﴾⟪2:165⟫.\nإذ تبرأ المتبعون من تابعهم، كقوله: ﴿لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ﴾⟪6:94⟫، وقوله: ﴿يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا﴾⟪29:25⟫، وقوله: ﴿ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ﴾⟪43:67⟫، وكما حكى عن الشيطان: ﴿مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ﴾⟪14:22⟫، وقوله: ﴿يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ﴾⟪26:88⟫\n⟦1:364⟧"}, {"a": [167], "v": 1, "p": 364, "ev": 1, "ep": 365, "sid": 365, "t": "قوله عز وجل:\n﴿وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ﴾⟪2:167⟫\nالآية (167) - سورة البقرة.\nالكر: هو العطف على الشيء بالذات، أو بالفعل، وعبر به عن الجبل المعقول، والكرير: تكرر الحشرجة في الصدر، والحسرة أصلها من حسرات القناع، وكأنها كشف ما غطى القصيرة من الهوى، وعلى ذلك:\nتحلى غطاء الرأس عني ولم يكد\nغطاء فؤادي ينجلي يستريح\nولما كان عند ذلك لغرض الندم والغم بما كان من الإنسان عبر به عنهما، فقيل أصابته حسرة، وقوله: كذلك أي كتبرؤ بعضهم من بعض يريهم الله أعمالهم حسرات عليهم، وبين الله تعالى ما يظهرونه من الندم باتباع مالا يغنى عنهم من الله شيئا وينسيهم مالا يجري نفعا، وقوله: أعمالهم دخل فيها [الأعمال التي فعلوها] ولم يريدوا وجه الله بها، فضلت عنهم، كقوله تعالى: ﴿ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعۡمَٰلَهُمۡ﴾⟪47:1⟫، وقوله: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫، وقوله: ﴿وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ﴾⟪24:39⟫، ودخل فيها الأعمال التي فرضت عليهم، فأحلوا بها، وعلى ذلك روي أن الجنة ترفع لهم، فينظرون إليها فيقال: تلك مساكنكم لو أطعتم الله عز وجل، وترفع النار لأهل الجنة فيقال لهم: تلك مساكنكم لو عصيتم الله - عز وجل -\n....\n⟦1:365⟧"}, {"a": [168], "v": 1, "p": 365, "ev": 1, "ep": 366, "sid": 366, "t": "قوله - عز وجل -:\n﴿يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ﴾⟪2:168⟫\nالآية (168) - سورة البقرة.\nالحلال: من حللت العقدة، وهو الذي حل لكنه عقدة الخطر، وجل بالمكان، أي حل عقد أحماله، كقولهم: حط رحله، وألقى أرواقه وحل الدين، أي حل عقد المطالبة، وحل من إحرامه، حل ما عقده على نفسه بالإحرام، وتحلة اليمين: ما تنحل به عقدة اليمين، والإحليل: لمخرج اللبن والبول لانحلال عقدته، والطيب: ما تستطيبه الشهوة المستقيمة والعقول الصحيحة أما بالإضافة إلي الشهوة المستقيمة فهو ما يشتهي لا لاضطرار كالجرذ والفأر والحرية والدم، أو لعادة سيئة كأكل الضب، ولهذا قال الشاعر:\nإنك لو ذقت الكسي بالأكباد ...\nلما تركت الضب يعدو بالواد\nوكعادة المخبث والمئل إلى الذكور عن النساء، وأما بالإضافة إلى العقول الصحيحة، فما يكون متناولا من حيث ما يجوز متبلغأ به إلى ما خلق لأجله وأن لا يقصد به شرك كما يذبح على النصب والخبيث على العكس، والحلال أعم من الطيب، والحرام أعم من الخبيثة فقد يكون حراما مالا يكون خبيثا في نفسه بالعقل كتحريم ما يقسم بالأزلام، واستعمال الذهب والفضة، ولبس الحرير على الذكور، وجمع بين الحلال والطيب في الآية ليفيد ما استطابه الطبع وأباحه الشرع، ولا ذكر إباحة الطيب، وكان كثيرا ما يزين الشيطان لبعض الناس ما ليس بالطبع الصحيح طيبا، كعادة المخنث اتبعه بقوله: ﴿وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ﴾⟪2:168⟫ كقوله: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ﴾⟪38:26⟫، وقد تقدم أن لا فرق بين أن يقال \" اتبع فلان الهوى \" وبين \" اتبع الشهوة أو الشيطان أو الحياة الدنيا في أن\n⟦1:366⟧\nالمقصد [بجميع ذلك] متابعة ما يصد عن سبيل الله- عز وجل-، ونبه بقوله: ﴿إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ﴾⟪2:168⟫ أن عداوته لا تخفى على ذي بصيرة، وهذا المعنى الذي أراده الشاعر وإن نقل اللفظ إلى الدنيا، حيث قال:\nإذا امتحن الدنيا لبيب تكشفت\n....\nله عن عدو في ثياب صديق.\nوقول آخر:\nعمرب لقد نصح الزمان وإنه ...\nلمن العجائب ناصح لا يشفق."}, {"a": [169], "v": 1, "p": 366, "ev": 1, "ep": 367, "sid": 367, "t": "قوله- عز وجل:\n﴿إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾⟪2:169⟫ الآية (169) - سورة البقرة.\nالسوء والفحشاء كل قبيح من نحو الزنا، والسرقة، والسكر، والقتل، والخيانة، والكذب والحسد والجهل [وكل ما يقال له سوء] يقال له فحش، لكن بنظرين مختلفين، فإنه سمي سوءا لاغتمام العاقل به، والفحشاء بأن يستفحشه، ونبه تعالى بأن الشيطان داع إلى إتيان الشر والسوء والفحش والتقول على الله عز وجل،\nإن قيل: إن كان التقول على الله عز وجل بما لا يعلم من عمل\nالشيطان، فكيف يصح الحكم بغالب الظن في كثير من الأحكام، فإن عامة فروع الفقه مبنية علي غلبة الظن، قيل: أما أولا: فليس ذلك تقولا على الله تعالى، وإنما ذاك تقول على أحكام، وقد فرق المتكلمون\n⟦1:367⟧\nبين الحكمة العلمية وبين الحكمة العملية وقالوا: كل ما كان من الحكمة العلمية، وهي التي لا عمل لها كالإيمان بالله وملائكة وكتبه ورسله، فإنه لا يجوز إن يحكم فيه ألا بالعلم المصون عن الشوائب، وما كان من الحكمة العملية فأصولها كذلك وأما فروعها: فيجور الحكم فيها لغلبة الظن لتفسيح صاحب الشرع لنا في ذلك، فصار حكمنا فليه من هذا الوجه حكما بالعلم، لأنه إذا قال لنا: إذا غلب في ظنك أن القبلة في هذا الجانب، فصل إليه، وإذا شهد عندك شاهدان مزكيان فاحكم بشهادتهما صرنا\nعالمين بأن هذا الحكم واجب علينا في الظاهر، وهذه مسلمة قد أحكمت في أصول الفقه، وأما سؤال من سأل من المتكلمين في هذه الآية بأنه كيف يأمرنا الشيطان ونحن لا نسمع قوله ولا نرى شخصه، وما الحكمة في إيصال الله- عز وجل- أمر الشيطان إلى نفوسنا، فهل وما يجري مجراه من الأسئلة سؤال من لم يتخط المحسومات والموهومات إلى باب المعقولات، ومحال الاشتغال معه [بهذه الحرمات]."}, {"a": [170], "v": 1, "p": 367, "ev": 1, "ep": 369, "sid": 368, "t": "قوله - عز وجل -:\n﴿وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ﴾⟪2:170⟫\nالآية (170) - سورة البقرة.\nذمهم الله بأنهم أبطلوا ما خص الله به الإنسان من الفكر والروية وركزه فيه من المعارف، وذلك أن الله تعالى ميز الإنسان بالفكر ليعرف به الخير من الشر في الاعتقاد والصدق من الكذب في المقال والجميل من القبيح في الفعال لم يتحر الحق والصدق الجميل، ويتجنب أضدادها،\n⟦1:368⟧\nوجعل له من نور العقل ما يستغنى به فيدله على معرفة مطلوبه، فلما حث الناس على تناول الحلال الطيب، ونهاهم من متابعة الشيطان بين حال الكفار في تركهم الرشاد واتباعهم الآباء والأجداد، ليحذر من الاقتداء بهم تاركين استعمال الفكر الذي هو صورة الإنسان [وحقيقته] ثم قال: ﴿أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا﴾⟪2:170⟫ أي يتبعونهم وإن كان آباؤهم جهلة- تنبيها أنه محال اتباع من لا عقل له ولا اهتداء ..\nإن قيل: ما فائدة الجمع بين قوله: (يعقلون، ويهتدون) وأحدهما يغنى عن الآخر؟\nقيل: قد تقدم أن العاقل يقال على ضربين، أحدهما: لمن يحصل له القوة التي بها يصح التكليف، والثاني: لمن يحصل له العلوم المكتسبة وهو المقصور ههنا، والمهتدي قد يقال لمن افتدى في أفعاله بالعالم وإن لم يكن مثله في العلم، فبين أنهم لا يعقلون ولا يهتدون، بعالم ووجه أخر، وهو أن يلقي ويهتدي وإن كان كثيرات ما يتلازمان، فإن العقل يزال بالإضافة إلى المعرفة، والاهتداء بالإضافة إلى العمل، فكأنه قيل: لا علم لهم صحيح ولا عمل مستقيم.\n⟦1:369⟧"}, {"a": [171], "v": 1, "p": 369, "ev": 1, "ep": 370, "sid": 370, "t": "قوله - عز وجل:\n﴿وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ﴾⟪2:171⟫\nالآية (171) - سورة البقرة.\nالنداء من قولهم: ندى الصوت، أي: غض الصوت، وأصله من الندى، فناداه، أي دعاه بندى صوته، ولما حكى لله عنهم ما زعموا أنهم يتبعون أباءهم دل على جهلهم بأنهم كأغنام ينعق بهم، فلا يعرفون مغزى الصوت ولا قصد المنادي، وقد تقدم الكلام في قوله، ﴿صُمُّۢ بُكۡمٌ عُمۡيٞ﴾⟪2:171⟫،\nإن قيل: كيف يكون مثلهم مثل الناعق والذين كفروا بالمنعوق به أشبه، والذي ينعق بالمنادي، والداعي أشبه قيل: التشبيه ضربان، تشبيه مفرد بمفرد وحقه أن يحمل أحدهما على الأخر [نحو زيد كأسد، وتشبيه جملة بجملة] ولا يراعي فيه مقابلة الألفاظ المفردة، فلما شبه قصة الذين كفروا في إعراضهم عن الداعي لهم إلا الحق بقصة الناعق، [قدم ذكر الناعق ليبنى] عليه ما يكون منه، ومن المنعوق به، وعلى هذا قوله ﴿مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ﴾⟪2:261⟫ وقوله: ﴿مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ﴾⟪3:117⟫ وقيل: عنى بالذين كفروا المتبوعين لا التابعين، ومعناه: مثل الدين كفروا في دعائهم أتباعهم كمثل الناعق بالغنم [الذي لا يسمع لها الصوت]\n....\n⟦1:370⟧"}, {"a": [172], "v": 1, "p": 370, "ev": 1, "ep": 370, "sid": 371, "t": "قوله - عز وجل -:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ﴾⟪2:172⟫\nالآية (172) - سورة البقرة.\nإن قيل: ما فائدة إعادة هذا المعنى وقد تقدم آنفا؟ وما الفرق بين هذا الخطاب والخطاب الأول؟ قيل في ذلك لطيفة وإشارة عجيبة، وذلك أنه حيث خاطب الناس كافة قال: ﴿كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا﴾⟪2:168⟫، فأباح لهم ذلك، ونبه أنه لم يحظر عليهم إلا تناول المحرم، وعقبه بالنهي عن اتباع الشيطان، وجعل الخطاب في هذه الأيام مخصوصا بالمؤمنين وأمرهم أن لا يتوسعوا في تناول\nما رزقوا، بل يتحروا من الطيب تحري الناس مما في الأرض، وأنه في الأول بالتحرر عن خطوات الشيطان، وهو الارتسام له فيما يتخطى به عن المباح، وأمر ههنا بالشكر لله تعالى الذي هو أرفع منزلة في العبادة على ما تقدم ذكره، ونبه بقوله: ﴿إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ﴾⟪2:172⟫ إن عبادته لا تتم إلا بشكره. . . قوله- عز وجل:"}, {"a": [173], "v": 1, "p": 370, "ev": 1, "ep": 372, "sid": 371, "t": "﴿إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ﴾⟪2:173⟫ الآية (173) - سورة البقرة.\nالإهلال: أصله وجود الهلال، ولما جرت العادة أن يكبروا عند رؤيته سمي التكبير إهلالا، بل قيل لرفع الصوت أيضا إهلال تشبيها بذلك حتى قيل: أهل الصبي، وأنا التهلل فظهور الهلال، فتارة يتصور لمعانه، فيقال: تهلل السحاب، وتهلل وجهه، وتارة يتصور شكله، فيقال: تهلل البعير إذا تقوس\n⟦1:371⟧\nإن قيل:\nلم ذكر تعالي بعض المحرمات وترك بعضها؟\nقيل: في ذلك جوابان، أحدهما: أن المسكوت عنه هو تفصيل الميتة، وقد ذكر ههنا الميتة المستوعبة لكل ما مات روحه عن غير ذكاة، والثاني: أنه لما كان القصد في هذه الآية حكم تناول المضطر دون استيعاب المحرمات،) ذكر الكل منها وترك البعض، والباغي في الأصل الطالب لما ليس له طلب والعادي: المتجاوز لا رسم له بالشرع، وقال الحسن وقتادة والربيع وابن زيد: عنى بقوله: (غير باغ غير متناول للذة، ولا عاد في المعصية طريق المحقين، وإلى نحوه ذهب الشافعي- رحيمة الله عليه، والظاهر يشهد له، لأن قوله: ﴿غَيۡرَ بَاغٖ وَلَا عَادٖ﴾⟪2:173⟫ متعلق بحال الاضطرار، فكأنه قال: \" من حصل له اضطرار \" لا على أحد هذين الوجهين، وعلى الأول تقديره: فمن اضطر فأكل غير باغ ولا عاد فيكون غير متعلق بمقدر محذوف، ومن أنكر ذلك وقال: إنكم تأمرونه بقتل نفسه إذا خطرتم ذلك عليه، وقتل نفسه محرم عليه عاصيا كانوا أو مطيعا، فجوابه إنا لم نأمره بذلك، بل أمرناه بأن ييخرج عن الحالة التي تكون الميتة محرمة عليه، وذلك بأن يتوب [وينزع عما هو عليه] وإلا كان متناولا لمحظور كما أن سفره محظور،\nفإن قيل: أليس من سفره طاعة؟ إنما أجل له للإضطرار.\nلا للطاعة، فإذن العلة لمدير الضرورة، فيجب أن تكون مطردة، قيل: بل العلة هي الضرورة مع حصول الطاعة، فقد قال الحكماء وهو الصحيح: إن الله تعالى جعل للإنسان طيبات الرزق وبشرط الإيمان، ولهذا قال: ﴿قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪7:32⟫، خالصة يوم أخذه فما أخذه الكفار من نعيم الدنيا، فإنما يأخذه اغتصابا في الحقيقة، ولذلك قد تستقيم أحوالهم، والآية تقتضي أن المضطر مخير في تناول أيها يريد وهو\n⟦1:372⟧\nالصحيح، لأن عليه إنقاذ روحه بجهده، فما رأه أقرب إلى إبقائه، فهو أولى بتناوله، واختلف إذا أضطر إلى شي من ذلك في دواء لا يسد غيره مسده، هل يجوز تناوله؟\nوالصحيح أنه يجوز للعلة التي لها أجيز تناوله للجوع، وكذا الخمر إذا اضطر إليها في دواء\nبحكم الأطباء أنه لا يسد غيره مسده، وأنه يفوت روحه إن لم يتناولها، قوله عليه الإسلام-، (إن الله- عز وجل لم يجعل شفاءكم فيما حرم عليكم)، فمعناه: إن قد رما فيه الشفاء غير محرم عليه، وعلى هذا نبه بالرخصة في شرب أبوال الإبل."}, {"a": [174], "v": 1, "p": 372, "ev": 1, "ep": 374, "sid": 373, "t": "قوله- عز وجل:\n﴿إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ﴾⟪2:174⟫\nالآية (174) - سورة البقرة.\nالبطن به شبه بطن الأمر وبطن الوادي، والبطن من العرب اعتبارا بأنهم كشخص واحد، وأن كل قبيلة منهم كعضو بطن وفخذ وكاهل، وعلى هذا الاعتبار قال الشاعر:\nالناس جسم وإمام الهدى ...\nرأس وأنت العين في الرأس\nوقيل: بطن إذا عظم بطنه نحو جسم وكبر، وبطنته عظمت بطنه، وسمي ما يشد عليه بطانا على بناء حرام وزمام والإبطن عرق تكشف البطن على بناء الأكحل، وأعاد الله تعالى وعيد كاتمي\n⟦1:373⟧\nأحكامه أثر ما.\nذكر من الأحكام، وما لم يقل ذلك من أهل الكتاب وتحذيرا لهذه الأمة أن يسلكوا سبيلهم وأكل النار تناول ما يؤدي إليها، وذكر الأكل لكونه المقصود الأول بتحصيل المال، وسماه بالمال الذي هو النار، وذكر في بطونهم تنبيها على شرههم، وتقبيحا لتضييع أعظم النعم لأجل المطعم الذي هو أحسن متناول من الدنيا، وعلى ذلك قال الشاعر:\nودع عنك عمرا إن عمرا مسالم\n....\nوهل بطن عمرو غير سبر لمطعم؟\nوقال آخر:\nكلوا في بعض بطنكم تعفو\nوعلى ذلك قوله تعالى: ﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ﴾⟪4:10⟫.\nوبقوله: \" ولا يكلمهم \" لم يعن نفي الكلام رأسا، فقد قال: ﴿فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ﴾⟪7:6⟫ وقال: ﴿وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ﴾⟪18:52⟫، وإنما أراد كلاما يقتضي جدوى، ولهذا قال الحسن:\nمعناه يغضب عليهم تنبيها أنهم بخلاف من قال فيهم: ﴿تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمٞۚ﴾⟪33:44⟫، وقيل: حقيقة كلمته حملته على الكلام نحو: حركته وخرجته، لأن من كلمته فقد استدعيت كلامه، فكأنه قيل: لا\n⟦1:374⟧\nيستدعي كلامهم نحو قولهم: ﴿وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ﴾⟪77:36⟫.\nوقد تقدم الكلام في الاشتراك والقليل والتزكية."}, {"a": [175], "v": 1, "p": 374, "ev": 1, "ep": 375, "sid": 375, "t": "قوله - عز وجل -:\n﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ﴾⟪2:175⟫\nالآية (175) - سورة البقرة.\nالضلالة والعذاب يتلازمان، وكذلك الهدى والمغفرة، لكن الضلال والهدى يقالان على الاعتبار بالدنيا، والعذاب والمغفرة على الاعتبار بالآخرة، وجلل تعاطيهم لما يؤديها إلى النار بمنزلة الصبر على النار، وهذا معنى قول الحسن: ليس صبرهم على النار، ولكن أراد ما أجرأهم على النار، وقول أبي عبيد:\nإن ذلك لغة \" يمانية \" بمعنى الجرأة، واحتجاجه بقول الأعرابي الذي قال لخصمه:\n\" ما أصبرك على الله؟، فتصور المجاز بصورة الحقيقة، لأن ذلك معناه: ما أصبرك على عذاب الله، وإلى هذا يعود قول من قال: ما أعملهم بعمل أهل النار! وما ألقاهم على النار!، وقد يوصف بالصبر من لا صبر له اعتبارا بالناظر إليه وتصورا أنه صابر، واستعماله لفظ التعجب في ذلك اعتبارا بالخلق لا بالخالق ...\n⟦1:375⟧"}, {"a": [176], "v": 1, "p": 375, "ev": 1, "ep": 375, "sid": 376, "t": "قوله - عز وجل -:\n﴿ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ﴾⟪2:176⟫\nالآية (176) سورة البقرة.\nذلك إشارة إلى.\nكل ما تقدم من العذاب والحكم والضلال، أي ذلك بسبب إنزاله الكتاب\nواختلافهم فيه، ويصح أن يكون نصبا، أي فعلنا ذلك \" بأن الله \".\nوأصل الاختلاف التخلف عن المنهج، وقيل: اختلفوا: أتوا بخلاف ما أنزل الله، وقيل: اختلفوا بمعنى خلفوا، نحو كسبوا واكتسبوا، وعملوا واعتملوا، أي صاروا خلفا فيه نحو: ﴿فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ﴾ ورثوا الكتاب، والشقاق وقد تقدم ذكره، ووصفه ببعيد تنبيها على بعدهم من الحق ..."}, {"a": [177], "v": 1, "p": 375, "ev": 1, "ep": 380, "sid": 376, "t": "قوله - عز وجل -:\n﴿لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ﴾⟪2:177⟫\nالآية (177) - سورة البقرة.\nالرقبة: أصل العتق، ويعبر بها عن الجملة كما يعبر عنها بالرأس والظهر والرجل واليد، ويعبر بها عن المملوك، وقيل رقبتة: إذا أصبت رقبته بها بالسلاح، وإما بالعين ناظرا إليه، ثم سمي المراعي للغير رقيبا، والخطاب في هذه الآية للكفار والمنافقين الذين أنكروا تغيير القبلة، وقيل: بل لهم وللمؤمنين، حيث قدروا أنهم نالوا البر كله بالتوجه إليها، ولما كانت القبلة أحد أركان الصلاة، والصلاة إحدى فعلات البر، بين تعالى أن ليس البر بمقصور على هذا الذي تعتبرونه، بل هو حملها.\nوالقبلة\n⟦1:376⟧\nركن من أركان واحدة منها، ثم عدها وذكر جملتها وفرائضها ونوافلها وبيان [ذلك أن جميع البر ضربان: اعتقاد، وأعمال فالاعتقاد] أصوله الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر، والأعمال ضربان: أحدهما ما يأخذ الإنسان به نفسه في معاشرة الناس من الأقارب والأباعد من ذلك المعروف والمواساة والتحبب إليهم بالسر والقول الحسن.\nوالثاني: ما يتخصص به في نفسه من إقامة العبادات واستعمال الصدق والوفاء والتواضع والصبر، وقد نبه الله عز وجل- على جميع ذلك بهذه الآية، إما على الاعتقاد فبقوله: ﴿مَنۡ ءَامَنَ بِٱللَّهِ﴾⟪2:177⟫ إلى قوله تعالى: ﴿وَٱلنَّبِيِّـۧنَ﴾⟪2:177⟫، وإما على ما يأخذ به الإنسان نفسه في معاشرة الناس فبقوله: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ﴾⟪2:177⟫ إلى قوله: ﴿وَفِي ٱلرِّقَابِ﴾⟪2:177⟫، فإنه ذكر الجود الذي هو من وجه أفضل هذه الأفعال، ومن وجه هو كل هذه الأفعال فإن الجواد كما يتبرع بماله يتورع عن مال غيره، وكما يجود بماله، يجود بجاهه وبطلاقة وجهه، وعند الحقيقة- بنفسه ، ودل على ما تخصص به في نفسه بقوله: ﴿وَأَقَامَ ٱلصَّلَوٰةَ﴾⟪2:177⟫ إلى أخر الآية، وكل ما سكت عنه فداخل تحت ما ذكره، أو منبة عليه، ونبه أن الآيتين بذلك بر، وهو المؤدي إلى النعيم المدلول عليه بقوله: ﴿إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ﴾، وبين تعالى بقوله: ﴿وَلَٰكِنَّ﴾⟪2:177⟫ بأن الذين تحروا ذلك إدا اعتبرتهم بأفعالهم وأقوالهم فهم الذين صدقوا، وإذا اعتبرتهم بأفعالهم وأحوالهم فهم المتقون، والصدق والتقوى وإن اختلفت حقيقتاهما فهما متلازمان،\nإن قيل:\nما وجه قوله- عليه السلام- لما سأله أبو ذر عن البر، وتلا عليه الآية، ولما سأله وابصة عنه: قال \" ما اطمأن إليه القلب، واطمأنت إليه النفس \" الخبر قيل إن أباذر سأله عن ذات البر، فبينه بالآية، ووابصة سأله عن كيفية تحريه والاشتياق من نفسه في تعاطيه، فبين بصفته.\n⟦1:377⟧\nإن قيل: لم لم يقل: (ولكن البر بر من أمن)، أو: ﴿ٱلۡبِرَّ مَنۡ ءَامَنَ﴾⟪2:177⟫ ليتطابقا؟\nقيل: قد ذكر النحويون في هذا وأمثاله أنه على حذف المضاف وإقامة المضاف إليه مقامه، ولكن وجه فائدته أنه إذا قل \" زيد بار \"، فإنه يعتبر في قولك: بار سيان الذات، والصورة والمختص بهامن معنى البر، وإذا قيل: \" زيد هو البر \"، ففيه مبالغة، وأنه صار لاختصاصه بهذا المعنى بحيث لا يرى منه إلا هذه الصورة مجردة عن العنصر الذي يجوز أن يتصور بغيره من الصور، وعلى هذا كل ما في معناه، نحو زيد أقبل وأدبر، وأكل وشربا وقوله: ﴿عَلَىٰ حُبِّهِۦ﴾⟪2:177⟫ أي على حب المؤمن، فيكون مضافا إلى الفاعل، وقيل: \" على حب المال \" ويكون مضافا إلى المفعول، ونبه بذلك أنه يبذله مع فرط الحاجة إليه نحو قوله تعالى: ﴿وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ﴾⟪59:9⟫، وقوله: ﴿لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ﴾⟪3:92⟫، وسئل- عليه السلام- أي الصدقة أفضل؟\nفقال: \" أن تتصدق وأنت صحيح شحيح تأمل العيش وتخشى الفقر \"، وقيل تقديره: على حب الإيثار، وذلك أن المحمدة التامة لم تهتز لإعطاء المال وتحب ذلك كما قال الشاعر:\nليس يعطيك للرجاء والخو\n....\nف ولكن يلد طعم العطاء\nوقيل: على حب الله أي يقصد به القربة لا طلب رياء ولا ثواب كما قال: ﴿إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ﴾⟪76:9⟫\n⟦1:378⟧\nإن قيل: لم قال: ﴿وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ﴾⟪2:177⟫ ولم يقل: ووفى كما قال: ﴿وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ﴾⟪2:177⟫ ليكون الكلام على نسق واحد؟\nقيل: ذلك لأمرين: أحدهما اللفظ، وهو أن الصلة متى طالت كان الأحسن أن يعطف على الموصول دون الصلة لئلا يطول فيقبح، والثاني: أنه ذكر في الأول ما هو داخل في حيز الشريعة، وغير مستفاد إلا منهما، فالحكمة العقلية تقتضي العدالة دون الجود، ولما ذكر الوفاء بالعهد وهو مما يقتضي العقول المجردة، صار عطفه على الأول أحسن.\nإن قيل: ولم نصب الصابرين؟ قيل: قل ذكر النحويون أن الصفات للمدح والذم إذا توالت قد يخالف بين إعرابها، وأنشدوا في ذلك:\nالنازلين بكل معترك ...\nوالطيبون معاقد الأزر\nإلي أبيات أخر.\nوفائدة ذلك أنهم إذا أرادوا أن كل واحد من تلك الأوصاف يستقبل بمدح أو ذم عظيم لو تجرد عما معه خالفوا بين إعرابها تنبيها على هذا المعنى، ولما كان الصبر من وجه مبدأ الفضائل [ومن وجه جامعا للفضائل] إذ لا فضيلة إلا وللصبر فيها أثر بليغ ولم يتم حسنها إلا به حتى روي:\n\" الصبر خير كله \"، قوله: (الصبر من الإيمان بمنزلة الرأس من الجسد) عن إعرابه تنبيها على هذا المقصد، واستوعب بقوله تعالى: ﴿وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ﴾⟪2:177⟫ أنواع الصبر، لأنه إما\n⟦1:379⟧\nأن يحتاج إليه في مقتنى يموت الإنسان، أو يريده فلا يناله، وهو البأساء أو فيما ينال جسمه من ألم وسقم وهو الضراء، أو في مدافعة مؤذيه له وهو اليأس.\nإن قيل: كيف قدم ههنا ذكر الآخرة وأخره في قوله: ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ﴾⟪4:136⟫؟\nقيل: يجوز أن يكون ذاك مع الواو لا يقتضي الترتيب من أجل أن الكافر لا يعرف الأخرة ولا يعني بها وهو أبعد الأشياء عن الحقائق عنده أخر ذكره، في قوله: ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ﴾⟪4:136⟫.\nولما ذكر حال المؤمنين، والمؤمن أقرب الأشياء إليه أمر الآخرة وكل ما يفعله ويتحراه يقصد به وجه الله ثم أمر وللآخرة قدم ذكرها تنبيها أن مراعاة الله- عز وجل- ومراعاة الآخرة، ثم مراعاة غيرهما\nإن قيل: كيف اختير الترتيب المذكور في قوله: ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ﴾⟪2:177⟫ قيل: لما كان أولى من يتفقده الإنسان بمعروفه أقاربه، ولهذا قال عليه السلام: \" لا يقبل الله صدقة وذو رحم محتاج \"، كأن تقديمها أولى، ثم أعقبه باليتامى، فالناس في المكاسب ثلاثة:\nمعيل وغير معول، ومعول معيل ومعول غير معيل، واليتيم معول غير معيل، فمواساته بعد الأقارب أولى، ثم ذكر المساكين، وهم الذين لا مال لهم حاضرا ولا غائبا، ثم ذكر ابن السبيل الذي قد يكون له مال غائب، ثم ذكر السائلين الذين منهم صادق وكاذب، ثم ذكر الرقاب الدين لهم أرباب يعولونهم فكل واحد ممن أخر ذكره أقل فقرا ممن قدم عليه.\n⟦1:380⟧"}, {"a": [178], "v": 1, "p": 380, "ev": 1, "ep": 381, "sid": 381, "t": "قوله - عز وجل -:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ﴾⟪2:178⟫\nالآية (178) - سورة البقرة.\nالقص: قطع الشيء على سبيل الاجتذاذ، ومنه قص شعره وقص أثره، وقص الحديث اقتطع كلاما حادثا حذف غيره، والقصة اسم منه، وحقيقة القصاص أن يفعل بالقاتل، والجارح مثل ما فعلا واعتبر الشافعي ومالك صورة الفعل حتى إن من رضخ رأس غيره بالحجر كان القصاص مثله، لكن مالكا يقول إنه يفعل به ذلك الفعل حتى يموت والشافعي يقوله: \" إن لم يمت من مثل فعله قتل بالسيف \"، ومن الفقهاء يعتبر المماثلة في القاتل والمقتول، فلا يقتل القاتل الحر بالعبد والمسلم بالذمي، والاختلاف أنه يعتبر في بعضهم كالمستأمن والكتابة يعتبر بها عن الإيجاب، وأصل ذلك أن الشيء يراد، ثم يقال، ثم يكتب فيعبر عن المراد الذي هو المبدوء بالكتابة التي هي المنتهى إن قيل على من يتوجه هذا الوجوب؟.\nقيل: على الناس كافة، فمنهم من يلزمه استيفاؤه وهو الإمام إدا طلبه الولي، ومنهم من يلزمه تسليم النفس وهو القاتل ، ومنهم من يلزمه المعاونة أو الرضا به، ومنهم من يلزمه أن لا يتعدى، بل يقتص أو يأخذ الدية، والقصد بالآية منع التعدي، فإن أهل الجاهلية كانوا يتعدون في القتل، وربما يرضى أحدهم إذا قتل عبد غيره لا يقتل حر ..\n⟦1:381⟧\nوقوله: ﴿فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ﴾⟪2:178⟫ ...\nمن القاتل، وأخوة ولي المقتول، ومعناه: من ترك له أخوه الذي هو ولى الدم شيئا من القصاص فليتبع في المطالبة بالدية المعروف، وليؤد إليه القاتل بإحسان ..\nإن قيل.\nلم قال: ﴿فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ﴾⟪2:178⟫ ولم يقل: \" فمن عفا له أخوه شيئا \"؟.\nقيل: العدول إلى هذا البناء للطيفة، وهي أنه لا فرق بين أن يكون صاحب الدم واحدا، فعفا أو جماعة فعفا واحد منهم أنه يبطل حق القصاص ويعدل حينئذ إلى الدية، فقال: ﴿فَمَنۡ عُفِيَ لَهُۥ﴾⟪2:178⟫ ليدل على هذا المعنى، وقيل: فاتباع: هو أمر للعافي بحسن المطالبة والهاء في قوله: أخيه، يجوز أن يكون للمقتول، ويكون لولي المقتول وجعله أخا لولي الدم لا للنسبة ولا للموالاة الدينية، ولكن للإحسان الذي أسداه إليه وأجرى العهد مجرى الخطأ في الرضا منه بالدية، وقوله: ﴿ذَٰلِكَ تَخۡفِيفٞ﴾⟪2:178⟫ أي خفف عنكم إذ جعل لكم الخيار في الحكمين، وقال بعضهم لم يكن العفو في أمة قبل هذه الأمة، وقوله: ﴿فَمَنِ ٱعۡتَدَىٰ﴾⟪2:178⟫ أي من تجاوز المشروع قاتلا كان أو ولي المقتول فإنه معاقب .."}, {"a": [179], "v": 1, "p": 381, "ev": 1, "ep": 382, "sid": 382, "t": "قوله - عز وجل -:\n﴿وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:179⟫\nالآية (179) - سورة البقرة.\nقوله: ﴿فِي ٱلۡقِصَاصِ حَيَوٰةٞ﴾⟪2:179⟫ كقول العرب: القتل أنقى للقتل، وذلك أنه يصير سببا للارتداع، وقال الجاحظ: تأويله أن العرب كانت تمتنع من تسليم القاتل إلى ولي المقتول خشية أن يقل عددهم، فقال الله تعالى: ﴿فِي ٱلۡقِصَاصِ حَيَوٰةٞ﴾⟪2:179⟫ أي إذا دفعتموه كثر عددكم، كما لأن الله تعالى ينمي كل قوم كثز فيهم القتل، ولهذا كثرت العلوية وقل العباسية، ولهذا قيل: السيف منماه فما تسلط على قبيلة إلا كثر عددهم، وقيل إن في ذلك حياة القاتل في الآخرة فإنه يرجى له الغفران، قال: وعلى هذا ما روي أن\n⟦1:382⟧\nالحدود كفارات لأهلها، وذلك بشرط أن يكون توبة، فالتوبة حق الله، والقصاص حق الآدمي، فإذا تاب واقتص منه فقد خرج من الذنوب ويرجى له الغفران، فقوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:179⟫ على التفسير الأول أي لعلكم ترتدعون عن القتل، وعلى الثاني: لعلكم لا تتحاشون من ترك القاتل والانقياد للقصاص."}, {"a": [180], "v": 1, "p": 382, "ev": 1, "ep": 383, "sid": 383, "t": "قوله- عز وجل:\n﴿كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ﴾⟪2:180⟫\nالآية (180) - سورة البقرة.\nالخير ههنا المال قليلا كان أو كثيرا، وقال بعض الناس: الخير لا يتناول إلا الكثير مستدلا بأن عليا- رضي الله عنه دخل على مولى له في موضعه، فقال: ألا أوصي وله سبع مائة أو ستمائة، فقال: لا، إنما قال- عز وجل (إن ترك خيرأ (، وليس لك مال كثير ...\nإن قيل: كيف سمي المال خيرا مطلقا وقد قليل إن المال ليس خيرا مطلقا حتى يراعي حال صاحبه فربما كان شرا له، وعلى هذا ذم الله تعالى في عام القرآن، وسماه تارة فتنة وتارة عدوا ..\nفيل: إن المال كما يكون خيرا قد يكون شرا، لكن جعل الله تعالى ههنا خيرا تنبيها على أن الوصية يستحب في المال الطيب دون الخبيث والمغصوب، فإن ذلك يجب رده إلي أربابه ومما تم بالوصية فقط، وقيل: هذه الآية منسوخة، فالإيجاب نسخ مما حمله، والوصية للوارث إيجابا وندبا، والناسخ لها عند الشافعية أية الميراث.\n⟦1:383⟧\nوعند بعضهم قول النبي عليه الصلاة والسلام: \" لا وصية لوارث \"، وقال بعض الناس: لا نسخ فيها، لأن معنى كتب ;كقوله: أريد وشرع، وما يراد ويشرع قد يكون ندبا وإيجابا، وقوله: الوصية للوالدين والأمر بين وإنما اقتضى عموما فإنه مخصوص بقوله- عليه السلام- \" لا وصية لوارث \" فصار ذلك للوالدين الكافرين أو المملوكين والأقارب الذين ليسوا بورثة، وتخصيص الآية في \" هو \" لا كتخصيصها فيما فوق الثلث والثلث كثير، وقال طاوس: \" إن أوصي لغير ذي قرابة لا يجوز احتجاجا، وظاهر الآية لا يقتضي ذلك ..."}, {"a": [181], "v": 1, "p": 383, "ev": 1, "ep": 384, "sid": 384, "t": "قوله - عز وجل -:\n﴿فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾⟪2:181⟫\nالآية (181) - سورة البقرة.\nأريد من بدل ذلك ولم يقل بدلها، وإن ما تقدم ذكر الوصية لكن يتناولها وغيرها من متعلقاتها، والهاء في \" إثمه \" للتبديل ومن: عام في الوصي والموصي له، والشاهد والحاكم وكل من له مدخل في ذلك إذا غير شيئا بعدما سمعه أي علمه، فإن إثم ما يجري في ذلك راجع إليه تنبيها على ما قاله - عليه السلام: (من سن سنة سيئة فعليه وزرها ووزر من عمل بها)\nوأعظم ذلك مالا يعرف المستن جود السان لها، كمن ادعي على صاحب الشرع خبرا يتعلق به\n⟦1:384⟧\nحكم، فيعتمد عليه الناس بعده، وإنما قال: ﴿عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ﴾⟪2:181⟫ ولم يقل عليه، ليبين أن إثمه للتبديل لا لغيره، ونبه بقوله: ﴿إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾⟪2:181⟫ أن ذلك وإن خفي على الناس، فلن يخفى عليه تعالى، فإنه يعلم خائنة الأعين وما تخفي الصدور."}, {"a": [182], "v": 1, "p": 384, "ev": 1, "ep": 385, "sid": 385, "t": "قوله - عز وجل -:\n﴿فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:182⟫\nالآية (182) سورة البقرة.\nجنف وخيف يتقاربان، لكن جنف استعمل للميل إلى الخير، وخيف في اليد إلى الجور، وخاف يقاربه، إلا أن أكثر ما يقال في الحاكم وخيفه أن يوصي لإنسان والمراد لغيره، كما قال طاوس: الخيف: التولج نحو أن يوصي الرجل لابن الابن ليوصل المال إلى أبيه أو لزوج ابنته ليوصله إليها، أو يخص في حيث يجب العموم، أو يعم حيث يجب الخصوص، وقوله: ﴿بَيۡنَهُمۡ﴾⟪2:182⟫ أي بين القوم الذين لهم مدخل في ذلك من الورثة والموصى لهم، وجاز إضمارهم لدلالة الكلام على ذكرهم.\nإن قيل: كيف قال: ﴿جَنَفًا أَوۡ إِثۡمٗا﴾⟪2:182⟫ والجنف هو الإثم؟ قيل: قد قال الربيع: الجنف في الخطأ، وإلا ثم في العمد، وقيل: الإثم: ما يكبر معصيته، والجنف ما دون ذلك، وخوفه هو أن يبدو له أمارة تقتضي حصول ذلك، ولا فرق بين أن يخاف منه ذلك، قبل موت الموصى فيرشده، أو بعد موته فيصلحه، وليس الإصلاح بمقصور على إيقاع الصلح دون استعمال الصلاح، بل يتناولهما ، وإنما قال: ﴿فَلَآ إِثۡمَ عَلَيۡهِۚ﴾⟪2:182⟫ لأنه لما خوف في الآية الأولى من تغيير الوصية بين أن النهي عن تغييره فيما لا\n⟦1:385⟧\nجنف فيه ولا إثم [على صاحبه]، فأما إذا كان فيه شي من ذلك فلا إثم [في تغييره]، وبين قوله تعالى: ﴿إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:182⟫ أنه يتجاوز عما عسى أن يسقط من المصلح ما لم يجده."}, {"a": [183], "v": 1, "p": 385, "ev": 1, "ep": 388, "sid": 386, "t": "قوله- عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:183⟫\nالآية (183) - سورة البقرة.\nالصوم في اللغة إمساك عما تنازع إليه النفس، ويقال ذلك في الطعام والشراب والنكاح نحو: ﴿إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا﴾⟪19:26⟫، في نحو:\n[خيل صيام، وأخرى غير صائمة]\nوصامت الريح إدا ركدت، والشمس إذا استوت في منتصف النهار كان لها وقفة، وفى الشرع إمساك المكلف بنية من الخيط الأبيض إلى الخيط الأسود عن المأكل والمشرب والمنكح والأستقاء والاستمناء والسعوط، وأما الأكل على سبيل السهو لا يخرجه عن أن يكون ممسكا حكما، ثم النية هل يجب أن يتقدم أو يجوز الاقتران به راجع إلى اختلاف المذاهب؟ واعلم أن الإمساك عن الأطيبين هو المقصود بالصوم وما عداه فلأنه يشبهه أو يؤدي إليه ...\nوللصوم فائدتان:\nإحداهما: قريبة، وهي أن يروض الإنسان به نفسه عما تدعوه إليه من الشهوات القبيحة، فإنه يعودها الصبر لكنها كما وصفها بقوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫، ومتى جعلت في حجر الشرع\n⟦1:386⟧\nفعودت الانقلاع\nفالنفس راغبة إذا رغبتها\n....\nوإذا ترد إلى قليل تقنع\nولكونه مفيدا للصبر، قال عليه السلام:: \" هذا شهر الصبر \"\nوقال تعالى: ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ﴾⟪2:45⟫ أي بالصوم.\nوالفائدة الثانية:\nوهي أن فيه الاقتداء بالملأ الأعلى على قدر الوسع والتنزه عن مشاكلة البهائم التي غاية شبع البطن والفرج، ووجه ذلك أن الإنسان مركب من بدن يسوسه سوسن الحيوان وغذاؤه المطاعم، ومن روح ذي عقل غذاؤه العلم والفضائل، ومتى أكثر غداء أحدهما قوي على ما نقص غذاؤه، ولهذا قال عليه السلام: \" رأس الدين الورع، وأفضل الورع قلة الطعام، ومن شبع ونام جثم على قلبه الشيطان \" وقيل: \" الجوع سحاب تمطر الحكمة \"،\nفإن قيل: فهلا أديم فرض الصوم إذا كان سببا\n⟦1:387⟧\nلهذه الفضيلة العظيمة (قيل: إن الله- عز وجل- ما خلق في الأرض وشهاه إلينا ليحرمناه، ولكن لينتفع به بقدر ما يحسن، وفي وقت ما يحسن، وألزمنا في بعض الأوقات التحرج عنه ليكون مدعاة إلى التعفف عن تناول مالا يجوز تناوله، وجعل الله تعالى فرضه على الأهلة ليتأدب الإنسان به في كل وقت من أوقات السنة صيفا وشتاء وربيعين ...\nإن قيل: على ماذا وقع التشبيه في قوله: ﴿كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ﴾⟪2:183⟫ قيل: قال بعضهم: إن ذلك على الصوم وكيفيته، لأن صوم من قبلنا لم يكن يحل لهم ألاكل بعد الرقاد، وكان على هذا في بدء الإسلام إلى أن نسخ بقوله: ﴿أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ﴾⟪2:187⟫، وإلى هذا ذهب معاذ، وهو المروي عن ابن عباس- رضي الله عنه- وقيل: كصوم من فبلنا في كونه أياما معدودات، وذلك في كل شهر ثلاثة أيام، ثم نسخ بقوله: ﴿شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ﴾⟪2:185⟫، وهو قول عطاء وقتادة، وردي عن معاذ بن جبل- رضي الله عنه- أن للصيام ثلاثة أحوال، وذلك أن النبي- عليه السلام- لما قدم المدينة، فكان يصوم في كل شهر ثلاثة أيام، ويصوم عاشوراء، ثم فرض بعد تسعة عشر شهرا شهر رمضان على التخيير، ثم فرضه على تضييق لمن كان مقيما صحيحا، وقيل:\nقد كان أوجب شهر رمضان على من كان قبلنا [من الأمم] فغيروا، ونقصوا، وزادوا، وهذا قول عهدته علي قائله، وقيل.\nالشبه وقع لوجوب الصوم فقط، وقد تقدم أن أصول هذه العبادات لم تزل واجبة على العباد وأن النسخ على ألسنة الأنبياء في فروعها وكيفياتها وقدرها [وأزمانها]، ونبه بقوله تعالى: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:183⟫ على العلة التي لأجلها أوجب، وهي قمع الشهوة، وما لأجلها لا يجوز أن يكون الصوم مرفوعا على أمة من الأمم، فإنه ذكر أنه سبب للتقوى، وتقوى الله عز وجل- واجبة\n⟦1:388⟧\nعلى كل مكلف عدى كل حال وفي كل زمان، ولهذا قال تعالى: ﴿وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ﴾⟪4:131⟫"}, {"a": [184], "v": 1, "p": 388, "ev": 1, "ep": 391, "sid": 389, "t": "قوله - عز وجل -:\n﴿أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ﴾⟪2:184⟫\nالآية (184) - سورة البقرة.\nالسفر: كشف الغطاء، يقال: سفر القناع عن وجهه، والريح السحاب أو الورق، ويقال له السفير، ومنه المسفرة، وسافر، والسفر الكتاب الكاشف عن الأغراض، والسفار للبعير كالحكمة للفرس، وهو ما يسفر عنه جماحه، تطوع يفعل من الطاعة، يقال، طاع وطوع، ومنه: ﴿فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ﴾⟪5:30⟫ والقدرة والاستطاعة والجهد والطاعة تتقارب، وبينها فروق، فالقدرة ما يظهر من القوة بقدر العمل لا زائدا عليه ولا ناقصا، والاستطاعة منهما ما يصير به الفعل طائعا له بسهولة، والوسع منها ما يسع له فعله بلا مشقة، والجهد ما يتعاطى به الفعل بمشقة، والطاقة منها بلوغ غاية المشقة.\nوقول الشاعر:\nكل امرئ عن طوقه\nأي عن غاية قدرته، لأن المقاتل لا يدع غاية من القدرة لا يبذلها قبل استسلامه للموت، وقوله: «أياما» يتعلق ب كتب عليكم \" أو ب \" كما كتب \"، أو بالصيام، وقوله: ﴿فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ﴾⟪2:184⟫ ظاهره يقتضي أن المريض والمسافر عليهما عدة من أيام أفطر أو لم يفطر، وإليه ذهب أهل الظاهر.\n⟦1:389⟧\nوعند عامة الفقهاء على إضمار الإفطار بدلالة إضماره في قوله: ﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ﴾⟪2:184⟫، وبدلالة الأخبار المروية في ذلك، ويقتضي أيضا أن السفر القليل والكثير سواء، وعند عامتهم يعتبر فيه قدر ما، فبعضهم حدده بمسيرة ثلاثة أيام، وبعض بمسيرة يومين، وبعض بمسيرة يوم، ولا خلاف في أن ن خرج إلى نزهة ببستانه في ظاهر بلده لا يفطر، ويقتضي ظاهره أيضا أن لا فرق بين أن يكون سفره لطاعة أو معصية، ولم يجوز الشافعي إلا في طاعة ويقتضي قوله ﴿فَعِدَّةٞ مِّنۡ أَيَّامٍ﴾⟪2:184⟫ أن لا فرق ين أن يقضيها متتابعة أو غير متتابعة، وقد حكى وجوب التتابع عن علي وابن مسعود- رضي الله عنهما-\nوقوله: ﴿مِّنۡ أَيَّامٍ أُخَرَۚ﴾⟪2:184⟫ عاد إلا في عيد الفطر والأضحى والثلاثة أيام التي بعدها وقوله: ﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ﴾⟪2:184⟫ ظاهره يقتضي أن المطيق له يلزمه فدية أفطر أو لم يفطر، لكن أجمعوا أنه لا يلزمه إلا مع شرط آخر فذهب الأصم إلا أن ذلك للمريض والمسافر وأن الذي يطيق الفدية منهما فأفطر، فعليه الفدية لمكان ما خفف عنه، كما جعل على المتمتع بما خفف عنه أن يهدي، وهذا ضعيف لأمرين، أحدهما: أنه لم يجر الفدية قبل ذكر ولا ما دل عليه، والثاني: أن المريض والمسافر قد أوجب عليهما عدة من أيام أخر، وذهب الشعبي وهو المروي عن ابن عباس- رضي الله عنهما- إلى أن الناس كانوا مخيرين في الابتداء بين أن يصوموا من غير فدية [وأن يفطروا ويقيدوا، ثم نسخ بالآية التي بعد، وتقديره: وعلى الذين يطيقونه فأفطروا إلى] وروي عن ابن عباس- رضي الله عنهما- في أصح الروايتين أن ذلك في الشيخ والشيخة الهمين والحامل والمرضع إذا خافتا على ولديهما، فلفظ (الطاقة) ههنا ينبيء عن ذلك، فإن الطاقة هدي التي تبلغ غاية المشقة ولا يخرج عن القدرة والعجز، ورأه، فذكر أن هؤلاء الذين يبلغ بهم الصوم غاية المشقة يجوز لهم الإفطار والفدية وقرئ\n⟦1:390⟧\n(يطوقونه) أي يتكلفونه بجهد، وقرئ) يطؤقونه) أي يحملون على أن يتطوقوا، وقرئ (مسكين) اعتبارا بكل واحد كقوله: ﴿فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ﴾⟪24:4⟫، وإنما يلزم كل واحد هذا القدر، (ومساكين) اعتبارا بجماعتهم، ﴿وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ﴾⟪2:184⟫ فقد قيل: مبني على ما تقدم، أي الصوم خير من الإفطار والكفارة، ون قال: ﴿ٱلَّذِينَ يُطِيقُونَهُۥ﴾⟪2:184⟫ للمسافرين والمرضى وقال هذا خطاب لهم، وكذا من قال: الشيخ الهم، ويجوز أن لا يكون خيرا فعل، وإنما المعنى: الخير في الصوم تنبيها على عظيم ثوابه، وذاك أن المراد من العبادة والإخلاص والنية، ولهذا قال عليه السلام: \" أخلص تكفك القليل من الغقل \"، ولما كانت الأفعال البدنية كثيرا ما يدخلها الرياء إلا الصوم فإنه لا يوقف عليه ما لم يخبر الإنسان عنه بلسانه، ولا عبادة يدخل فيها الإنسان بالنية المجردة إلا الصوم ...\nقال عليه السلام: \" يقول الله- عز وجل الصوم لي وأنا أجزي به \"، ثم قال: ﴿إِن كُنتُمۡ تَعۡلَمُونَ﴾⟪2:184⟫ أي: إن عرفتم ما فيه من المنفعة، وتحققتم ما يثمره لكم لم تتهاونوا في تحمله.\n⟦1:391⟧"}, {"a": [185], "v": 1, "p": 391, "ev": 1, "ep": 395, "sid": 392, "t": "قوله - عز وجل -:\n﴿شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ﴾⟪2:185⟫\nالآية (185) - سورة البقرة.\nشهرة الشيء: ظهوره للكافة، وقل شهر أمره وسيفه إذا جرده والشهر مدة مشهورة والمشاهرة المعاملة به كالمعاومة والمياومة [والمسانهة] والرمض شدة وقع الشمس، وسمي رمضان لمطابقته في ابتداء موضوع الاسم له شدة الحر، لأن الشهور سميت [في الأصل] بمطابقة بعض ما عرض فيها من الأحوال في ابتداء موضوعها والإرادة أصلها من: راد يرود إذا سعى في مهل للطلب، ومنه الرايد، والمرود للميل، ولمعنى المهل قيل رويدا، وقد تقدم حقيقة الإرادة، والقرآن أصله من القرى، وهو ضم ما كان متفرقا، ومنه: \" ما قرأت الناقة سلاقط \"، أي ما لم تضمه إلى نفسها ولم تجمعه في رحمها، ولا يتناول إلا على المنزل على محمد- عليه السلام- والكتاب عام، والفرقان قيل إنه يتناول القرآن والتوراة-\nإن قيل: فلم سمي بذلك؟\n⟦1:392⟧\nقيل: إما بالنظر الحلال، فلأنه جامع للسور والأيام، وإما على نظر أدق من ذلك، فلأنه جمع فيه كل شيء محتاج إليه الناس من أمر معاشهم ومعادهم مما يتبلغون به إلى الأخره، ولهذا قال تعالى: ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ﴾⟪6:38⟫، وقال: ﴿وَتَفۡصِيلَ كُلِّ شَيۡءٖ﴾⟪12:111⟫، والعسر صعوبة الشيء وعسره وعسيرآ، وعسر عمل شماله وذلك إما تصور الصعوبة ما تتعاطى بها وإما لاعتقاد العسر فيها بسواها، واليسر ضده، واليسير للضار بين على الحرور بالقداح لليسارهم، وقوله:\n﴿شَهۡرُ رَمَضَانَ﴾⟪2:185⟫ مبتدأ، وخبره الذي، ومن لم يجعل الأول منسوخا قال: تقديره: \" هو شهر رمضان \" أو يكون بدلا من الصيام، وقوله: هدى، أي هاديا ، وقال عطية بن الأسود ولابن عباس: \" في نفسي شي، وهو أنه قال: ﴿شَهۡرُ رَمَضَانَ﴾⟪2:185⟫ وقال: ﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ﴾⟪97:1⟫، وقال: ﴿إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ﴾⟪44:3⟫، وقد أنزل الله- عز وجل- القرآن في جميع الشهور، فقال: الليلة المباركة ليلة القدر، وليلة القدر في شهر رمضان، وقد أنزل الله القرآن جملة إلى البيت المعمور، ثم أنزل على محمد - صلى الله عليه وسلم - الله رسلا، وعلي هذا قوله: ﴿وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا﴾⟪17:106⟫.\nوقيل فيه: أي في سببه وتخصيصه بذلك وإن شاركه فيه غيره فعلى سبيل التعظيم، وعلى هذا \" في ليلة القدر \"، أي في سببه وتفصيله، وإليه ذهب الضحاك ...\nإن قيل:\nإذا كان الهدى مقتضيا للبينات، فما فائدة ﴿وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ﴾⟪2:185⟫؟ قيل: القرآن يهدي على\n⟦1:393⟧\nضربين، أحدهما أن يدل على سبيل المجمل، والثاني: على سبيل التفصيل، فبين أن فيه هدى على الجملة، وبينات أي ما يوضح ويكشف على سبيل التفصيل، ففرق بين الحق والباطل، فصار ذكر البينات والفرقان بعد الهدى ذكر الخاص بعد العام، وجواب أخر، وهو أنه قد تقدم أن الهدى على ضربين هداية إلى سبيل الله المعنية بقوله تعالى: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ﴾⟪16:125⟫، وهداية إلى الله المعنية بقوله عز وجل: ﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ﴾⟪12:108⟫، فالإشارة بقوله: (هدى) إلى الأولى، وبقوله: ﴿وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ﴾⟪2:185⟫ إلى الثانية والفرقان مصدر في الأصل [كالغفران والكفران] وسمي به القرآن لكونه فارقا بين الحق والباطل في الاعتقاد والصدق والكذب في المقال، والجميل والقبيح في الأفعال، وقوله: ﴿فَمَن شَهِدَ﴾⟪2:185⟫ عام في كل مكلف حاضرا كان أو مسافرا، لكن أخرج منه المسافر والمريض، ولم يدخل فيه الحائض لدلالة الإجماع عليه فمنهم من اعتبر الشهود في ابتدائه، فقال: \" من شهده وهو مقيم فعليه صومه سافر أو لم يسافر \" وإليه ذهب أمير المؤمنين علي- رضي الله عنه-، ومنهم من اعتبر ذلك في أجزائه، وإليه ذهب عامة الفقهاء، وقال أبو حنيفة: - رحمه الله: \" من كان صحيح العقل في بعض رمضان، فعليه صوم كله، لأنه شهد الشهر \"، وعند الشافعي أن كل يوم لم يكن فيه صحيح العقل لا يلزمه صومه، ولا خلاف أن الصبي إذا بلغ في أثناء الشهر لم يلزمه قضاء ما تقدم من الشهر.\nإن قيل: لم أعاد ذكر الشهر، ولم يقل: \" فمن شهده \"؟\nقيل: لأمرين: أحدهما: تعظيما لذكره، لأن ما يعظم فد يعاد ذكره مع كل حكم يحدد له.\nوالثاني: ليس يحل الصوم على من كان شهد الشهر الذي أنزل فيه القرآن فقط، فلذلك أعاد ذكره ...\n⟦1:394⟧\nإن قيل:\nفلم قال: (فليصمه) ولم يقل فيصم فيه؟\nقيل: قد ذكر بعض النحويين أن القائل إدا قال اليوم ضربته زيدا، إنما يقال إذا استوعب اليوم لضربه، وإذا قيل: ضربت فيه، فهو أن يضرب فيه في بعض أوقاته، فنبه بقوله: (فليصمه) على الاستيعاب.\nإن قيل: لم أعيد ذكر المريض والمسافر؟\nقيل: إما على قول من يجعل اللحية منسوخة فليس أن حكمها مراعى في الناسخ كما هو مراعى في المنسوخ، وإن ذلك لم يرتفع بارتفاع التخيير، وأما على قول غيره فللتأكيد أولا ولتعليق ما علق به من الحكم ثانيا، وهو قوله: ﴿يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ﴾⟪2:185⟫، وذكر الفقهاء أن إرادة اليسر هي مما رخص للمسافر والمريض، وذهب غيرهم إلى أن إرادة الله عز وجل اليسر لمن أوجب عليه الصوم عليهم كما هي للمفطر والصائم جميعا، ففي الصوم أعظم اليسرين، وعلى هذا قال الأعرابي: \" أقصد البلد المبارك لأصوم هذا الشهر المبارك \"، فقيل له: أفي هذا الحر؟\nفقال: \" من الحر أفر \"\nوقيل لآخر: أتكد نفسك في العبادة، فقال: \" راحتها أريد، فإذن في إيجاب \" الله تعالى الصوم\nأعظم اليسرين. . . إن قيل: عدى أي وجه تعليله بما علل به من قوله: ﴿وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ﴾⟪2:185⟫؟\nقيل: بين تعالى.\nأن ما أوجبه من الصوم عينا وقضاء إرادة لتكميل العدة المقتضية للتقوى المذكورة في قوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:183⟫، ﴿وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ﴾⟪2:185⟫ ولم يرد به التفوه بلفظ التكبير فقط،\n⟦1:395⟧\nبل أراد معرفة كبريائه وعظمته وإن كان فيه دلالة أن التكبير مستحب ..\nإن قيل: لم قال: ﴿وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ﴾⟪2:185⟫ فأخدل الواو فيه؟ قيل:.\nيجوز أن تتعلق اللام بفعل مضمر،\nكأنه قيل: (ولتكملوا العدة) أمر بما أمر، ويجوز أن يكون معطوفأ على قوله: ﴿ٱلۡيُسۡرَ﴾⟪2:185⟫، كأنه قيل: (يريد بكم اليسر وتكميل العدة)، فادخل فيه اللام كما أدخل في قوله: ﴿يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ﴾⟪4:26⟫."}, {"a": [186], "v": 1, "p": 395, "ev": 1, "ep": 397, "sid": 396, "t": "قوله - عز وجل -:\n﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ﴾⟪2:186⟫\nالآية (186) - سورة البقرة.\nإن قيل.\nكيف فصل بين الآية الأولى وبين التي بعد هذه وهما في حكم رمضان بهذه الآي وهي قد اختلفت عنهما؟، قيل بل هي من تمام الآية الأولى، لأنه لما حث على تكبيره وشكره على ما قيضه لهم من إتمام الصوم، بين أن الذين تذكرونه وتشكرونه قريب منكم ومجيب لكم إذا دعوتموه، ثم تمم ما بقي من أحكام الصوم، ولم يرد بالقرب ههنا القرب المكاني، وإنما ذلك قربة تقتضيه إفضاله ووجود آثاره المشار إليها بقوله: ﴿وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ﴾⟪50:16⟫، وروي أن موسى قال: \" أقريب \" أنت فأنا جيك؟ أم بعيد فأناديك؟ فقال:\n\" لو حددت لك البعد لما انتهيت إليه، ولو حددت لك القرب لما اقتدرت عليه، وقد روي أن النبي - صلى الله عليه وسلم - سئل عن ذلك، فأنزل الله- عز وجل- هذه الآية فبين، تعالى أفضاله على عباده، وضمن أنهم\n⟦1:396⟧\nإذا دعوه أجابهم، وعليه نبه بقوله تعالى: ﴿ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ﴾⟪40:60⟫\nإن قيل: قد ضمن في الآيتين أن من يدعوه يجيبه، وكم رأينا من داع له لا يجاب؟، قيل: إنه ضمن الإجابة لعباده، ولم يرد بالعباد من ذكرهم بقوله: ﴿إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا﴾⟪19:93⟫، وإنما عني بهم الموصوفين ...\nفي قوله- عز وجل- ﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾ الآية، وقوله: ﴿وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا﴾⟪25:63⟫ لآية، ولدعائهم شرائط، وهي أن تدعو بأحسن الأسماء كما قال الله تعالى: ﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ﴾⟪7:180⟫، ويخلص له النية الافتقار ولا يرغب إليه فيما تنزه الأكابر عن مسئلة مثله ولا ما يستعين به على معاداته، وأن يعلم أن نعمته فيما يمنعه من دنياه كنعمته فيما أعطاه، ومعلوم أن من هذا حاله مجاب الدعوة، وأنه من جملة من وصفه النبي عليه السلام بقوله:\n\" رب ذي طمرين لا يؤبه به لو أقسم على الله لأبره \" ثم قال: ﴿فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي﴾⟪2:186⟫ أي إذا كنت لهم بهذه المنزلة فحري أن يستجيبوا لي إدا دعوتهما وأن يؤمنوا بي - راجين رشدهم، وإنما قال: ﴿فَلۡيَسۡتَجِيبُواْ لِي﴾⟪2:186⟫ ولم يقل ليجيبوا للطيفة، وهي أن حقيقة الاستجابة طلب الإجابة وإن كان قد يستعمل في معنى الإجابة، فبين أن العباد متى تحروا إجابته بقدر وسعهم فإنه يرضى عنهم ...\nإن قيل: كيف جمع بين الاستجابة والإيمان وأحدهما يغني عن الأخر؟\n⟦1:397⟧\nفإنه لا يكون مستجبا لله -عز وجل- من لا يكون مؤمنا، ولا مؤمنا من لا يكون مستجيبا، قيل أحدهما وإن يضمن الآخر من حيث الاعتبار، فذكرها ليطمئن، فإن إجابته ارتسام أوامره ونواهيه التي يتولاه الجوارح، والإيمان هو الاعتقاد الذي تقتضيه القلوب، وأيضا فإن الإيمان المعني هاهنا هو الإيمان الذكور في قوله:\n﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾⟪8:2⟫\nوذلك بعد الإجابة، وقد تقدمت منازل الإيمان."}, {"a": [187], "v": 1, "p": 397, "ev": 1, "ep": 400, "sid": 398, "t": "قوله- عز وجل:\n﴿أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ﴾⟪2:187⟫\nالآية (187) - سورة البقرة.\nالرفث كل كلام يتضمن ذكر الجماع، وجعل كناية عنه، وعدي بإلى لتضمنه معنى الإفضاء والخيانة بنقض العهد، ولهذا قوبل بالوفاء الدال على التمام، والحد ما يمنع أحد الشيئين من الآخر، فتارة يتصور منه المنع، نحو قوله تعالى: ﴿إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ﴾، وقيل للثواب حداد، وتارة تصور منه الفصل فقيل : حد الدار، وجه شبه الحد في الكلام، وقيل: حد الرأي لكونه مانعا له ولغيره عن بواقعة مثله، وحد السيف ما يفصل بينه وبين الجانب الأخر، ثم تصور منه الدقة، فقيل: أحددت السيف، وسمي الحديد لكثرة وجود هذه الصورة فيه، والعكوف: الإقامة على الشيء والحبس عليه، فتارة يراعي منه الإقامة فلا يعدي نحو: ﴿سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ﴾⟪22:25⟫، وتارة يراعى منه الحبس\n⟦1:398⟧\nوالوقف، فيعدي نحو قوله: ﴿وَٱلۡهَدۡيَ مَعۡكُوفًا﴾⟪48:25⟫، وقوله: ﴿هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ﴾⟪2:187⟫ جعل اللباس كناية عن الزوج، لكونه سترا لنفسه ولزوجه أن يظهر منهما سوء، كما أن اللباس يمنع أن تبدو السوءة، وعلى ذلك جعلت المرأة إزارا، وسمي النكاح حصنا، لكونه حصينا لذويه عن تعاطي القبيح.\nوقال الأصم:\nمعنى قوله: ﴿هُنَّ لِبَاسٞ لَّكُمۡ﴾⟪2:187⟫ أي كأن يعطي كل واحد على الآخر ما يتعاطاه من الاختيارمن قولهم: لبست عليه ذيلي، وقيل: سبب نزول هذه الآية أن المباحات كانت تحظر على الصائم بعد الرقاد، فقيل: إن عمر قالت له امرأته لما راودها: قد أعفيت، فظن أنها اعتلت عليه، فواقعها، فذكر ذلك للنبي- عليه السلام- وقيل: كان شيخ من الأنصار يقال له \" صرمة \" قعد ينتظر امرأته لتصنع له طعاما، فنام وترك الطعام، فرآه النبي- علية السلام- في اليوم الثاني شاحبا، فسأله، فأخبره، فأنزل الله تعالى هذه الآية والاختيان مراودة الخيانة وتخصيصه من دون قوله: (تخونون) لفائدة، وهي أن\n⟦1:399⟧\nالمخاطبين لم يكونوا كلهم خانوا وكلهم أوجلهم قد اختانوا، لأن الاختيان هو أن تتحرك الشهوة وتدعوه، ولذلك خص لفظ النفس المعنية بقوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫، وكفى للتنبيه على اختيان النفس شهادة من حلفها بذلك علما بقوله تعالى: ﴿عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ﴾⟪2:187⟫، فاختيان النفس مخادعتها ومدافعتها إما بمساعدة أو بمخالفة وقوله تعالى: ﴿وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ﴾⟪2:187⟫ إشارة في تحري النكاح إلى لطيفة، وهي أن الله تعالى جعل لنا شهوة النكاح لبقاء نوع الإنسان إلى غاية، كما جعل لنا شهوة الطعام لبقاء أشخاصنا إلى غاية، فحق الإنسان أن يتحرى بالنكاح ما جعل الله لنا سعلى حسب ما يقتضيه العقل والديانة، فمتى تحرى به حفظ النسل وحصن النفس على الوجه المشروع، فقد ابتغى ما كتب الله له، وإلى هذا أشار من قال:\nعنى الولد به الخيط الأبيض بياض النهار، وبالخيط الأسود سواد الليل، وروي أن عدي بن حاتم عمد إلى عقالين أبيض وأسود، ثم جعل ينظر إليهما ويأكل إلا أن يتبين أحديهما ن الأخر، فأخبر النبي- عليه السلام- بالذي صنع، فقال: إنك لعريض الوساد، إنما ذاك سواد الليل بياض النهار وقول: ﴿ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ﴾⟪2:187⟫ تنبيه على ابتداء التحريم إلى انتهائه، وكما نهى عن المباشرة في حال الصوم نهي عنها في حال الاعتكاف وظاهر ذكر المساجد يقتضي جوار الاعتكاف في كل مسجد ...\n⟦1:400⟧"}, {"a": [188], "v": 1, "p": 400, "ev": 1, "ep": 401, "sid": 401, "t": "قوله - عز وجل -:\n﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:188⟫\nالآية (188) - سورة البقرة.\nالإدلاء: إرسال الدلو في البئر، واستعير للتوصل إلى الشيء، وعلى هذا قول الشاعر:\nفليس الرزق عن طلب حثيث\n....\nولكن ألق دلوك في الدلاء\nوعلى هذا النحو سمي الوسيلة المانحة في قول الشاعر:\nولي مانح لم يورد الماء قبله ...\nمعل وأشطان الطوي كثير\nوالأكل عبارة عن الإنفاق، إذ هو أهم ما يصرف إليه المال، وأكل المال بالباطل صرفه إلى ما ينافيه الحق، وهو التبذير والإسراف قليلا كان الإنفاق أو كثيرا، ولهذا قيل:\n(رب إنفاق قليل هو إسراف، وكثير هو اقتصاد) ...\n، وقوله: (وتدلوا) أي لا تدلوا، وكما نهي عن تبذير الأموال نهى أن يدلي بها إلى الحكام على سبيل الرشوة، وتوصلا إلى اقتطاع أموال الناس، وقيل: معناه: لا يأكل بعضكم مال بعض غصبا أو خيانة فيلجؤوهم إلى المرافعة إلى الحكام، فلا يحكم عليكم لعدم البينة فتستبينوا إلى أن تأكلوا فريقا ن أموال الناس بالإثم، وقيل: من يتولى أموال\n⟦1:401⟧\nالأيتام، فيأكل بعضا ويدفع إلى الحكام بعضا، والوجه الأول أجود، لأنه قال: ﴿وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم﴾⟪2:188⟫ ثم قال: لتأكلوا ففصل بين الأمرين، والوجهان الآخران داخلون في عمومه وقوله: ﴿وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:188⟫ أي إن أخفى علمكم على الناس، فإنه لا يخفى عليكم تنبيها أن الاعتبار بما عليه الأمر في نفسه وما علمتم منه لا بما يظهر، ونبه - عليه السلام - على ذلك بقوله:\n(إنكم تختصمون إلى، ولعل بعضكم ألحن بحجته من بعض، فمن حكمت له بشيء من حق أخيه، فلا يأخذن منه قليلا ولا كثيرا، فإنما أقطع له قطعة من النار) وقال: (البر ما اطمأنت إليه النفس).\nقوله - عز جل:"}];
